-- Seed de demonstração para a Sprint 2.
-- Idempotente: limpa apenas os registros prefixados com 'demo-chat-' antes de recriá-los.
-- Fornece 9 campanhas com ciclo de vida completo: RASCUNHO, AGUARDANDO_APROVACAO, APROVADA, REPROVADA e ARQUIVADA.
-- Cada campanha inclui histórico completo e coerente de conversas na tabela mensagem_chat.

BEGIN;

-- 1. Limpeza idempotente dos registros anteriores da demo
-- Desvincula simulações das campanhas e versões
UPDATE simulacao
   SET campanha_id = NULL, versao_id = NULL
 WHERE chat_id LIKE 'demo-chat-%';

-- Limpa referência da versão para mensagem_chat para evitar trava de FK
UPDATE campanha_versao
   SET ultima_mensagem_id = NULL
 WHERE campanha_id IN (SELECT id FROM campanha WHERE chat_id LIKE 'demo-chat-%');

-- Remove logs de status das campanhas demo
DELETE FROM campanha_status_log
 WHERE campanha_id IN (SELECT id FROM campanha WHERE chat_id LIKE 'demo-chat-%');

-- Remove versões das campanhas demo
DELETE FROM campanha_versao
 WHERE campanha_id IN (SELECT id FROM campanha WHERE chat_id LIKE 'demo-chat-%');

-- Remove mensagens do chat (deve ocorrer antes de remover as simulações, pois mensagem_chat referencia simulacao)
DELETE FROM mensagem_chat
 WHERE chat_id LIKE 'demo-chat-%';

-- Remove simulações da demo
DELETE FROM simulacao
 WHERE chat_id LIKE 'demo-chat-%';

-- Remove campanhas da demo
DELETE FROM campanha
 WHERE chat_id LIKE 'demo-chat-%';

-- 2. Criação das campanhas da demo
DO $body$
DECLARE
  v_gabriela_id INT;
  v_sergio_id   INT;
  v_silvia_id   INT;
  v_camp_id     BIGINT;
  v_sim_id      BIGINT;
  v_versao_id   BIGINT;
  v_sim_v1_id   BIGINT;
  v_sim_v2_id   BIGINT;
  v_versao1_id  BIGINT;
  v_versao2_id  BIGINT;
  v_msg_id      BIGINT;
  v_msg_v1_id   BIGINT;
  v_msg_v2_id   BIGINT;
BEGIN
  -- Busca IDs dos usuários padrão criados pela migration V4
  SELECT id INTO v_gabriela_id FROM usuario WHERE email = 'gabriela@camplana.com.br';
  SELECT id INTO v_sergio_id   FROM usuario WHERE email = 'sergio@camplana.com.br';
  SELECT id INTO v_silvia_id   FROM usuario WHERE email = 'silvia@camplana.com.br';

  --------------------------------------------------------------------------
  -- 1. Campanha em RASCUNHO (só a Gabriela vê em 'Minhas Campanhas')
  --------------------------------------------------------------------------
  INSERT INTO campanha (nome, autor_id, chat_id, status, criada_em, atualizada_em)
  VALUES ('Campanha Fim de Ano - Rascunho', v_gabriela_id, 'demo-chat-rascunho', 'RASCUNHO', '2026-10-24 10:00:00+00', '2026-10-24 10:00:00+00')
  RETURNING id INTO v_camp_id;

  INSERT INTO campanha_status_log (campanha_id, versao_id, de, para, usuario_id, em, justificativa)
  VALUES (v_camp_id, NULL, NULL, 'RASCUNHO', v_gabriela_id, '2026-10-24 10:00:00+00', NULL);

  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-rascunho', v_gabriela_id, 'usuario', NULL, NULL, $txt$Lana, qual foi o total de vendas por marca no histórico de dezembro de 2025?$txt$, NULL, NULL, '2026-10-24 10:02:10+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-rascunho', v_gabriela_id, 'lana', NULL, NULL, $txt$Consultei o banco para dezembro de 2025. Registramos 4.967 vendas somando R$ 13.187.602,83. A marca PRETO liderou com R$ 10.467.513,69 (3.844 vendas), seguida pela BRANCO com R$ 1.029.063,80 (404 vendas), VERMELHO com R$ 816.957,70 (336 vendas), AZUL com R$ 732.187,64 (335 vendas), AMARELO com R$ 91.410,00 (29 vendas) e CINZA com R$ 50.470,00 (19 vendas).$txt$, NULL, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "consultar_banco", "descricao": "Vendas por marca em dez/2025", "tabelas_acessadas": ["funcionario_loja", "loja", "marca", "venda"], "competencias": ["2025-12"], "filtros": "vendas de 01/12/2025 a 31/12/2025 agrupadas por marca", "sql_executado": "SELECT m.cod_marca, m.descr_marca, COUNT(*) AS qtd_vendas, ROUND(SUM(v.vlr_venda)::numeric, 2) AS total_valor FROM venda v JOIN funcionario_loja fl ON fl.funcionario_id = v.funcionario_id AND fl.date_ref = date_trunc('month', v.date_ref)::date JOIN loja l ON l.id = fl.loja_id JOIN marca m ON m.id = l.marca_id WHERE v.date_ref >= '2025-12-01' AND v.date_ref <= '2025-12-31' GROUP BY m.cod_marca, m.descr_marca ORDER BY m.cod_marca LIMIT 50", "registros_retornados": 6, "dados": [{"cod_marca": "10", "descr_marca": "PRETO", "qtd_vendas": 3844, "total_valor": 10467513.69}, {"cod_marca": "20", "descr_marca": "BRANCO", "qtd_vendas": 404, "total_valor": 1029063.8}, {"cod_marca": "30", "descr_marca": "AZUL", "qtd_vendas": 335, "total_valor": 732187.64}, {"cod_marca": "40", "descr_marca": "VERMELHO", "qtd_vendas": 336, "total_valor": 816957.7}, {"cod_marca": "50", "descr_marca": "AMARELO", "qtd_vendas": 29, "total_valor": 91410.0}, {"cod_marca": "60", "descr_marca": "CINZA", "qtd_vendas": 19, "total_valor": 50470.0}], "tempo_ms": 380, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-24 10:02:15+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-rascunho', v_gabriela_id, 'usuario', NULL, NULL, $txt$Quero criar um incentivo de fim de ano de 15 a 24/12/2025 para todas as marcas com +0,5% para vendedores e assistentes, sem incluir gerentes.$txt$, NULL, NULL, '2026-10-24 10:05:00+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-rascunho', v_gabriela_id, 'lana', NULL, NULL, $txt$Registrei a proposta preliminar para 15 a 24/12/2025 em todas as marcas com acréscimo de 0,5% para vendedores e assistentes (cargos 100, 200 e 300). Falta definir a Meta Financeira da Campanha. Qual o valor que deseja estabelecer?$txt$, $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "draft-fim-ano", "faltantes": ["meta_vendas"], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-12-24", "data_inicio": "2025-12-15"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 0.5, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["ALL"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": null, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Incentivo Fim de Ano 0,5% de 15 a 24/12/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "registrar_parametros_regra", "descricao": "Ficha da campanha registrada; falta informar: Meta Financeira da Campanha (R$)", "tabelas_acessadas": [], "competencias": ["2025-12"], "filtros": "marcas: ALL; cargos: 100, 200, 300; periodo: data_inicio: 2025-12-15; data_fim: 2025-12-24", "sql_executado": null, "registros_retornados": 0, "dados": null, "tempo_ms": 0, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-24 10:05:04+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-rascunho', v_gabriela_id, 'usuario', NULL, NULL, $txt$Pode fixar a meta em R$ 1.500.000,00.$txt$, NULL, NULL, '2026-10-24 10:07:20+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-rascunho', v_gabriela_id, 'lana', NULL, NULL, $txt$Meta de R$ 1.500.000,00 incluída com sucesso na ficha. Todos os parâmetros obrigatórios foram preenchidos.$txt$, $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "draft-fim-ano", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-12-24", "data_inicio": "2025-12-15"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 0.5, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["ALL"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 1500000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Incentivo Fim de Ano 0,5% com meta 1,5M", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "registrar_parametros_regra", "descricao": "Ficha da campanha registrada", "tabelas_acessadas": [], "competencias": ["2025-12"], "filtros": "marcas: ALL; cargos: 100, 200, 300; meta: 1500000.00; periodo: 2025-12-15 a 2025-12-24", "sql_executado": null, "registros_retornados": 0, "dados": null, "tempo_ms": 0, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-24 10:07:24+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-rascunho', v_gabriela_id, 'usuario', NULL, NULL, $txt$Pensando no movimento forte de Natal, vamos subir o percentual de acréscimo de 0,5% para 1,0%.$txt$, NULL, NULL, '2026-10-24 10:09:40+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-rascunho', v_gabriela_id, 'lana', NULL, NULL, $txt$Atualizei a comissão para 1,0% mantendo todas as marcas, cargos 100, 200 e 300 e meta de R$ 1.500.000,00. A ficha está atualizada no painel para simulação.$txt$, $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "draft-fim-ano", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-12-24", "data_inicio": "2025-12-15"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 1.0, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["ALL"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 1500000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Incentivo Fim de Ano 1% de 15 a 24/12/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "registrar_parametros_regra", "descricao": "Ficha da campanha registrada", "tabelas_acessadas": [], "competencias": ["2025-12"], "filtros": "marcas: ALL; cargos: 100, 200, 300; pct_acrescimo: 1.0; meta: 1500000.00; periodo: 2025-12-15 a 2025-12-24", "sql_executado": null, "registros_retornados": 0, "dados": null, "tempo_ms": 0, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-24 10:09:44+00');
  INSERT INTO simulacao (usuario_id, chat_id, campanha_id, status, etapa, ficha, resultado, modelo, tentativas, criada_em, concluida_em)
  VALUES (v_gabriela_id, 'demo-chat-rascunho', v_camp_id, 'CONCLUIDA', 'Concluída', $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "draft-fim-ano", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-12-24", "data_inicio": "2025-12-15"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 1.0, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["ALL"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 1500000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Incentivo Fim de Ano 1% de 15 a 24/12/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $json${"meta": {"atingida": true, "diferenca": 350000.0, "meta_vendas": 1500000.0, "vendas_periodo": 1850000.0, "pct_atingimento": 123.33}, "codigo": "import pandas as pd\nimport numpy as np\nfrom datetime import datetime\n\nDATA_INICIO = \"2025-12-01\"\nDATA_FIM = \"2025-12-14\"\nPCT_ACRESCIMO = 0.5\nMARCAS_ALVO = [\"10\", \"20\", \"30\", \"40\", \"50\", \"60\"]\nCARGOS_ALVO = [\"100\", \"200\", \"300\"]\n\ndef aplicar_regra(bases, apuracao_base, competencias):\n    rh = bases[\"rh\"]\n    vendas = bases[\"vendas\"]\n    \n    # Filtrar vendas no período da regra\n    dt_inicio = pd.to_datetime(DATA_INICIO)\n    dt_fim = pd.to_datetime(DATA_FIM)\n    \n    vendas_periodo = vendas[\n        (vendas[\"data_venda\"] >= dt_inicio) & \n        (vendas[\"data_venda\"] <= dt_fim)\n    ]\n    \n    # Base de cálculo no período da regra para cada matrícula\n    # Se for gerente (cod_cargo == \"150\"), a base é a soma das vendas da loja inteira no período\n    # Para os demais cargos alvo (100, 200, 300), a base é a venda própria do funcionário no período\n    \n    # 1. Vendas próprias no período por matrícula\n    vendas_proprias = vendas_periodo.groupby([\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"], as_index=False)[\"vlr_venda\"].sum()\n    vendas_proprias = vendas_proprias.rename(columns={\"vlr_venda\": \"base_periodo\"})\n    \n    # 2. Vendas totais da loja no período (para gerentes)\n    vendas_loja = vendas_periodo.groupby([\"competencia\", \"cod_loja\"], as_index=False)[\"vlr_venda\"].sum()\n    vendas_loja = vendas_loja.rename(columns={\"vlr_venda\": \"base_loja_periodo\"})\n    \n    # Mesclar com apuracao_base para garantir o escopo correto e identificar gerentes\n    apuracao_simulada = apuracao_base.copy()\n    \n    # Identificar quais registros são elegíveis\n    elegivel = (\n        apuracao_simulada[\"cod_marca\"].isin(MARCAS_ALVO) & \n        apuracao_simulada[\"cod_cargo\"].isin(CARGOS_ALVO) &\n        apuracao_simulada[\"competencia\"].isin(competencias)\n    )\n    \n    # Mapear bases do período para a apuração\n    # Primeiro, juntamos vendas próprias\n    df_trab = apuracao_simulada[[\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"]].copy()\n    df_trab = df_trab.merge(\n        vendas_proprias[[\"matricula\", \"competencia\", \"base_periodo\"]],\n        on=[\"matricula\", \"competencia\"],\n        how=\"left\"\n    )\n    df_trab[\"base_periodo\"] = df_trab[\"base_periodo\"].fillna(0.0)\n    \n    # Juntar vendas da loja\n    df_trab = df_trab.merge(\n        vendas_loja[[\"competencia\", \"cod_loja\", \"base_loja_periodo\"]],\n        on=[\"competencia\", \"cod_loja\"],\n        how=\"left\"\n    )\n    df_trab[\"base_loja_periodo\"] = df_trab[\"base_loja_periodo\"].fillna(0.0)\n    \n    # Calcular base específica para o acréscimo\n    # Se cargo for 150 (gerente), a regra diz que acréscimo para gerentes incide sobre a venda da loja,\n    # MAS o cargo 150 NÃO está em CARGOS_ALVO (\"100\", \"200\", \"300\"). Portanto, cargo 150 NUNCA recebe acréscimo.\n    # Logo, apenas cargos 100, 200, 300 recebem, e para eles a base é a venda própria.\n    \n    delta = np.where(\n        elegivel,\n        df_trab[\"base_periodo\"] * (PCT_ACRESCIMO / 100.0),\n        0.0\n    )\n    delta = np.round(delta, 2)\n    \n    apuracao_simulada[\"comissao\"] = np.round(apuracao_simulada[\"comissao\"] + delta, 2)\n    \n    # Montar o DataFrame de contribuicoes apenas com quem teve delta != 0\n    df_trab[\"delta\"] = delta\n    mask_contribuicoes = (df_trab[\"delta\"] != 0) & (df_trab[\"competencia\"].isin(competencias))\n    \n    contribuicoes = df_trab.loc[mask_contribuicoes, [\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\", \"delta\"]].copy()\n    contribuicoes[\"elemento_ref\"] = \"pct_acrescimo\"\n    contribuicoes = contribuicoes[[\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\", \"elemento_ref\", \"delta\"]]\n    \n    return {\n        \"apuracao_simulada\": apuracao_simulada,\n        \"contribuicoes\": contribuicoes\n    }\n", "totais": {"baseline": 180000.0, "simulado": 225000.0, "diferenca": 45000.0, "diferenca_pct": 25.0}, "trilha": {"modelo": "gemini-3.5-flash-lite", "passos": [{"dados": null, "ordem": 1, "filtros": "vendas de 01/12/2025 a 14/12/2025; marcas 10, 20, 30, 40, 50, 60", "situacao": "SUCESSO", "tempo_ms": 102, "descricao": "Bases de dez/2025: 467 pessoas no RH, 4967 vendas de 01/12 a 14/12, 24 linhas de % por marca e cargo", "ferramenta": "carregar_bases", "competencias": ["2025-12"], "mensagem_erro": null, "sql_executado": "SELECT f.matricula, to_char(fl.date_ref, 'YYYY-MM') AS competencia,\n       l.cod_loja, m.cod_marca, c.cod_cargo,\n       f.data_admissao, f.data_demissao\nFROM funcionario f\nJOIN funcionario_loja fl ON fl.funcionario_id = f.id\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = f.id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(fl.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT f.matricula, to_char(v.date_ref, 'YYYY-MM') AS competencia,\n       v.date_ref AS data_venda, v.vlr_venda::float8 AS vlr_venda,\n       l.cod_loja, m.cod_marca, c.cod_cargo\nFROM venda v\nJOIN funcionario f ON f.id = v.funcionario_id\nJOIN funcionario_loja fl ON fl.funcionario_id = v.funcionario_id\n     AND fl.date_ref = date_trunc('month', v.date_ref)::date\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = v.funcionario_id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(v.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT m.cod_marca, c.cod_cargo, mc.pct_comiss::float8 AS pct_comiss\nFROM marca_cargo mc\nJOIN marca m ON m.id = mc.marca_id\nJOIN cargo c ON c.id = mc.cargo_id\nWHERE mc.date_ref = (SELECT max(date_ref) FROM marca_cargo);", "tabelas_acessadas": ["cargo", "funcionario", "funcionario_cargo", "funcionario_loja", "loja", "marca", "marca_cargo", "venda"], "registros_retornados": 5458}, {"dados": null, "ordem": 2, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1050, "descricao": "Comissão atual (regras 5a a 5g): 