  VALUES ('demo-chat-aguardando', v_gabriela_id, 'usuario', NULL, NULL, $txt$Lana, qual foi o volume diário de vendas registrado no final de novembro de 2025 entre os dias 20 e 28?$txt$, NULL, NULL, '2026-10-25 14:01:10+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-aguardando', v_gabriela_id, 'lana', NULL, NULL, $txt$Consultei as vendas entre 20/11/2025 e 28/11/2025. Registramos 721 vendas nos dias 24 a 28/11, somando R$ 2.406.125,93. O pico de faturamento ocorreu em 27/11, com R$ 1.204.721,79 em 246 vendas.$txt$, NULL, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "consultar_banco", "descricao": "Vendas de 20/11 a 28/11/2025", "tabelas_acessadas": ["venda"], "competencias": ["2025-11"], "filtros": "vendas entre 20/11/2025 e 28/11/2025 agrupadas por data", "sql_executado": "SELECT v.date_ref AS data_venda, COUNT(*) AS qtd_vendas, ROUND(SUM(v.vlr_venda)::numeric, 2) AS total_valor FROM venda v WHERE v.date_ref BETWEEN '2025-11-20' AND '2025-11-28' GROUP BY v.date_ref ORDER BY v.date_ref LIMIT 50", "registros_retornados": 5, "dados": [{"data_venda": "2025-11-24", "qtd_vendas": 280, "total_valor": 319528.26}, {"data_venda": "2025-11-25", "qtd_vendas": 68, "total_valor": 292139.14}, {"data_venda": "2025-11-26", "qtd_vendas": 67, "total_valor": 287817.31}, {"data_venda": "2025-11-27", "qtd_vendas": 246, "total_valor": 1204721.79}, {"data_venda": "2025-11-28", "qtd_vendas": 60, "total_valor": 301919.43}], "tempo_ms": 290, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-25 14:01:15+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-aguardando', v_gabriela_id, 'usuario', NULL, NULL, $txt$Quero cadastrar a Campanha Virada de Novembro: de 20 a 28/11/2025, +1,0% em todas as marcas para vendedores e assistentes (cargos 100, 200 e 300).$txt$, NULL, NULL, '2026-10-25 14:02:40+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-aguardando', v_gabriela_id, 'lana', NULL, NULL, $txt$Ficha registrada com +1,0% de 20 a 28/11/2025 em todas as marcas para cargos 100, 200 e 300, excluindo gerentes. Ainda falta definir a Meta Financeira da Campanha. Qual o valor pretendido?$txt$, $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-aguardando", "faltantes": ["meta_vendas"], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-11-28", "data_inicio": "2025-11-20"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 1.0, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["ALL"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": null, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Campanha Virada de Novembro 1% de 20 a 28/11/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "registrar_parametros_regra", "descricao": "Ficha da campanha registrada; falta informar: Meta Financeira da Campanha (R$)", "tabelas_acessadas": [], "competencias": ["2025-11"], "filtros": "marcas: ALL; cargos: 100, 200, 300; periodo: data_inicio: 2025-11-20; data_fim: 2025-11-28", "sql_executado": null, "registros_retornados": 0, "dados": null, "tempo_ms": 0, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-25 14:02:44+00');
