  VALUES (v_camp_id, 1, v_sim_id, $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-aguardando", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-11-28", "data_inicio": "2025-11-20"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 1.0, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["ALL"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 2200000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Campanha Virada de Novembro 1% de 20 a 28/11/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $json${"meta": {"atingida": true, "diferenca": 206125.93, "meta_vendas": 2200000.0, "vendas_periodo": 2406125.93, "pct_atingimento": 109.37}, "codigo": "import pandas as pd\nimport numpy as np\nfrom datetime import datetime\n\nDATA_INICIO = \"2025-11-20\"\nDATA_FIM = \"2025-11-28\"\nPCT_ACRESCIMO = 1.0\nMARCAS_ALVO = [\"10\", \"20\", \"30\", \"40\", \"50\", \"60\"]\nCARGOS_ALVO = [\"100\", \"200\", \"300\"]\nCOMPETENCIAS = [\"2025-11\"]\n\ndef aplicar_regra(bases, apuracao_base, competencias):\n    vendas = bases[\"vendas\"].copy()\n    \n    # Converter data_venda para datetime, caso não esteja\n    vendas[\"data_venda\"] = pd.to_datetime(vendas[\"data_venda\"])\n    \n    # Filtrar vendas na janela especificada\n    dt_inicio = pd.to_datetime(DATA_INICIO)\n    dt_fim = pd.to_datetime(DATA_FIM)\n    vendas_janela = vendas[(vendas[\"data_venda\"] >= dt_inicio) & (vendas[\"data_venda\"] <= dt_fim)]\n    \n    # Filtrar por marcas_alvo\n    vendas_janela = vendas_janela[vendas_janela[\"cod_marca\"].astype(str).isin(MARCAS_ALVO)]\n    \n    # 1. Base para cargos normais (100, 200, 300 - exceto gerente 150): soma das vendas próprias na janela por matrícula, competencia, cod_marca, cod_cargo, cod_loja\n    vendas_normais = vendas_janela[vendas_janela[\"cod_cargo\"].astype(str).isin(CARGOS_ALVO)]\n    base_normais = vendas_normais.groupby(\n        [\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"], as_index=False\n    )[\"vlr_venda\"].sum()\n    base_normais.rename(columns={\"vlr_venda\": \"base_periodo\"}, inplace=True)\n    base_normais[\"tipo_base\"] = \"normal\"\n    \n    # 2. Base para gerentes (cod_cargo == \"150\"): soma das vendas TOTAIS da loja na janela\n    # O enunciado diz: \"o GERENTE (cod_cargo '150') recebe pct sobre a venda TOTAL da loja no mês. Um acréscimo para gerentes, portanto, incide sobre a venda da loja no período da regra: some TODAS as vendas da loja (de todos os cargos) na janela; NUNCA filtre as vendas por cod_cargo antes dessa soma. Os cargos-alvo filtram quem RECEBE, não quais vendas contam para o gerente.\"\n    # E os gerentes também precisam estar contemplados nos cargos_alvo? A regra diz \"cargos_alvo\": [\"100\", \"200\", \"300\"]. Espere, o gerente é \"150\". Se \"150\" não está em cargos_alvo, ele não recebe?\n    # Vamos verificar os cargos_alvo da regra: [\"100\", \"200\", \"300\"]. O gerente (\"150\") NÃO está em cargos_alvo!\n    # Portanto, apenas os cargos 100, 200, 300 recebem o acréscimo.\n    \n    # Vamos mapear cada linha de apuracao_base elegível\n    apuracao_simulada = apuracao_base.copy()\n    \n    # Identificar quem recebe: competencia em competencias, cod_marca em MARCAS_ALVO, cod_cargo em CARGOS_ALVO\n    elegivel = (\n        apuracao_simulada[\"competencia\"].isin(competencias) &\n        apuracao_simulada[\"cod_marca\"].astype(str).isin(MARCAS_ALVO) &\n        apuracao_simulada[\"cod_cargo\"].astype(str).isin(CARGOS_ALVO)\n    )\n    \n    # Mesclar para pegar a base de cálculo da janela para os cargos normais\n    # Para o cargo 150 (gerente), se estivesse incluído, seria a venda total da loja. Como não está, focamos nos cargos normais.\n    # Vamos juntar base_normais com apuracao_simulada nas chaves: matricula, competencia, cod_loja, cod_marca, cod_cargo\n    \n    merged = apuracao_simulada.merge(\n        base_normais[[\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\", \"base_periodo\"]],\n        on=[\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"],\n        how=\"left\"\n    )\n    merged[\"base_periodo\"] = merged[\"base_periodo\"].fillna(0.0)\n    \n    # Calcular o delta: base_periodo * (PCT_ACRESCIMO / 100.0)\n    # Apenas para os elegíveis\n    delta_calculado = np.where(\n        merged[\"competencia\"].isin(competencias) &\n        merged[\"cod_marca\"].astype(str).isin(MARCAS_ALVO) &\n        merged[\"cod_cargo\"].astype(str).isin(CARGOS_ALVO),\n        merged[\"base_periodo\"] * (PCT_ACRESCIMO / 100.0),\n        0.0\n    )\n    \n    merged[\"delta\"] = [round(d, 2) for d in delta_calculado]\n    \n    # Atualizar comissao em apuracao_simulada\n    apuracao_simulada[\"comissao\"] = apuracao_simulada[\"comissao\"] + merged[\"delta\"]\n    \n    # Comissão nunca pode ficar negativa (embora delta seja positivo)\n    apuracao_simulada[\"comissao\"] = apuracao_simulada[\"comissao\"].apply(lambda x: round(max(0.0, x), 2))\n    \n    # Recalcular o delta real caso tenha batido em limite ou ajuste, mas aqui é só acréscimo positivo.\n    # Para garantir consistência exata: delta = nova_comissao - comissao_antiga (ou o delta calculado arredondado)\n    # O enunciado pede: \"A soma dos delta de cada matrícula/competência precisa ser igual a apuracao_simulada.comissao - apuracao_base.comissao.\"\n    merged[\"delta\"] = apuracao_simulada[\"comissao\"] - apuracao_base[\"comissao\"]\n    merged[\"delta\"] = merged[\"delta\"].apply(lambda x: round(x, 2))\n    \n    # Filtrar apenas quem teve delta != 0\n    contribuicoes = merged[merged[\"delta\"] != 0.0].copy()\n    contribuicoes[\"elemento_ref\"] = \"pct_acrescimo\"\n    \n    contribuicoes = contribuicoes[[\n        \"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\", \"elemento_ref\", \"delta\"\n    ]]\n    \n    return {\n        \"apuracao_simulada\": apuracao_simulada,\n        \"contribuicoes\": contribuicoes\n    }\n", "totais": {"baseline": 515738.39, "simulado": 539474.53, "diferenca": 23736.14, "diferenca_pct": 4.6}, "trilha": {"modelo": "gemini-3.5-flash-lite", "passos": [{"dados": null, "ordem": 1, "filtros": "vendas de 20/11/2025 a 28/11/2025; marcas 10, 20, 30, 40, 50, 60", "situacao": "SUCESSO", "tempo_ms": 113, "descricao": "Bases de nov/2025: 469 pessoas no RH, 721 vendas de 20/11 a 28/11, 24 linhas de % por marca e cargo", "ferramenta": "carregar_bases", "competencias": ["2025-11"], "mensagem_erro": null, "sql_executado": "SELECT f.matricula, to_char(fl.date_ref, 'YYYY-MM') AS competencia,\n       l.cod_loja, m.cod_marca, c.cod_cargo,\n       f.data_admissao, f.data_demissao\nFROM funcionario f\nJOIN funcionario_loja fl ON fl.funcionario_id = f.id\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = f.id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(fl.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT f.matricula, to_char(v.date_ref, 'YYYY-MM') AS competencia,\n       v.date_ref AS data_venda, v.vlr_venda::float8 AS vlr_venda,\n       l.cod_loja, m.cod_marca, c.cod_cargo\nFROM venda v\nJOIN funcionario f ON f.id = v.funcionario_id\nJOIN funcionario_loja fl ON fl.funcionario_id = v.funcionario_id\n     AND fl.date_ref = date_trunc('month', v.date_ref)::date\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = v.funcionario_id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(v.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT m.cod_marca, c.cod_cargo, mc.pct_comiss::float8 AS pct_comiss\nFROM marca_cargo mc\nJOIN marca m ON m.id = mc.marca_id\nJOIN cargo c ON c.id = mc.cargo_id\nWHERE mc.date_ref = (SELECT max(date_ref) FROM marca_cargo);", "tabelas_acessadas": ["cargo", "funcionario", "funcionario_cargo", "funcionario_loja", "loja", "marca", "marca_cargo", "venda"], "registros_retornados": 5491}, {"dados": null, "ordem": 2, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1116, "descricao": "Comissão atual (regras 5a a 5g): R$ 515.738,39", "ferramenta": "comissao_atual", "competencias": ["2025-11"], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 469}, {"dados": null, "ordem": 3, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 4612, "descricao": "Código gerado por gemini-3.5-flash-lite em 1 tentativa, conferido com o cálculo de referência", "ferramenta": "gerar_codigo", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 4, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 826, "descricao": "Código executado no sandbox", "ferramenta": "executar_sandbox", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 469}, {"dados": null, "ordem": 5, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 782, "descricao": "6 conferências passaram: colunas obrigatórias, mesmas pessoas e meses da comissão atual, sem comissão negativa, contribuições somam a diferença, escopo da regra, cálculo de referência", "ferramenta": "conferir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 6, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1239, "descricao": "Custo adicional de R$ 23.736,14", "ferramenta": "resumir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}], "campanhas": [{"nome": "Especificação nov/25, item 5f", "tipo": "ACRESCIMO", "autor": null, "versao": null, "data_fim": "2025-11-30", "pct_novo": null, "aprovador": null, "aprovada_em": null, "campanha_id": null, "data_inicio": "2025-11-24", "justificativa": "Black Friday: +1% nas vendas de 24 a 30/11, todas as marcas, exceto gerentes", "pct_acrescimo": 1.0}], "premissas": ["Gerentes (150) excluídos", "Cargos elegíveis: 100, 200, 300", "Marcas incluídas: 10, 20, 30, 40, 50, 60", "Período: de 20/11/2025 a 28/11/2025", "Acréscimo de comissão: +1.0%", "Simulação sobre vendas que já aconteceram: supõe que as pessoas venderiam o mesmo com a regra nova.", "A comparação com a comissão atual é o número mais confiável; o total absoluto é apurado por nós, não é a folha oficial.", "A comissão atual ainda não aplica proporcional de admissão/demissão nem férias e afastamentos."], "tentativas": 1}, "impacto": {"pessoas_total": 469, "maior_acrescimo": 278.81, "media_por_pessoa": 81.29, "pessoas_impactadas": 292}, "retorno": {"provisorio": true, "custo_pct_venda": 0.99, "custo_por_real_acima_meta": 0.12}, "rule_id": "rule-aguardando", "cenarios": [{"tipo": "sem_marca", "titulo": "Sem a marca Preto", "economia": 19337.86, "marcas_alvo": ["20", "30", "40", "50", "60"], "pct_acrescimo": 1.0, "cabe_no_orcamento": null, "custo_incremental": 4398.28}], "conflitos": [{"nome": "Black Friday 2025", "tipo": "ACRESCIMO", "autor": "Gabriela", "cargos": ["100", "200", "300"], "marcas": ["10", "20", "30", "40", "50", "60"], "status": "APROVADA", "versao": 1, "data_fim": "2025-11-30", "campanha_id": null, "data_inicio": "2025-11-24", "sobreposicao": {"data_fim": "2025-11-28", "data_inicio": "2025-11-24"}}], "orcamento": null, "por_cargo": [{"codigo": "100", "baseline": 291061.06, "simulado": 310637.32, "diferenca": 19576.26}, {"codigo": "150", "baseline": 155412.93, "simulado": 155412.93, "diferenca": 0.0}, {"codigo": "200", "baseline": 63708.26, "simulado": 67209.65, "diferenca": 3501.39}, {"codigo": "300", "baseline": 5556.14, "simulado": 6214.63, "diferenca": 658.49}], "por_marca": [{"codigo": "10", "baseline": 407902.53, "simulado": 427240.39, "diferenca": 19337.86}, {"codigo": "20", "baseline": 50758.07, "simulado": 52872.29, "diferenca": 2114.22}, {"codigo": "30", "baseline": 8641.86, "simulado": 9300.35, "diferenca": 658.49}, {"codigo": "40", "baseline": 43005.63, "simulado": 44349.96, "diferenca": 1344.33}, {"codigo": "50", "baseline": 2900.03, "simulado": 3138.43, "diferenca": 238.4}, {"codigo": "60", "baseline": 2530.27, "simulado": 2573.11, "diferenca": 42.84}], "ressalvas": ["Simulação sobre vendas que já aconteceram: supõe que as pessoas venderiam o mesmo com a regra nova.", "A comparação com a comissão atual é o número mais confiável; o total absoluto é apurado por nós, não é a folha oficial.", "A comissão atual ainda não aplica proporcional de admissão/demissão nem férias e afastamentos."], "explicacao": "No histórico, as vendas desse período somaram R$ 2.406.125,93, 109% da meta de R$ 2.200.000,00, ficando 9,4% acima da meta e R$ 206.125,93 acima dela. O custo extra da campanha foi de R$ 23.736,14, representando 4,6% sobre a comissão atual de R$ 515.738,39, com 292 de 469 pessoas recebendo o acréscimo, em média R$ 81,29 cada, sendo o maior de R$ 278,81, a loja 35 com o maior custo extra de R$ 778,60, que corresponde a 3,3% do total. A maior parte do custo extra vem da marca Preto, com 81% do total, e o cargo que mais recebe o acréscimo é o vendedor loja, com 82% do total. A marca Preto é o que mais pesa no custo, então sugiro o cenário calculado 'Sem a marca Preto', com acréscimo de 1,00% e custo extra de R$ 4.398,28.", "observacao": "Resultado da IA conferido com o cálculo determinístico.", "tentativas": 1, "competencias": ["2025-11"], "maiores_lojas": [{"codigo": "35", "baseline": 11927.2, "simulado": 12705.8, "diferenca": 778.6}, {"codigo": "26", "baseline": 10676.28, "simulado": 11333.81, "diferenca": 657.53}, {"codigo": "28", "baseline": 9155.82, "simulado": 9801.45, "diferenca": 645.63}, {"codigo": "24", "baseline": 8612.07, "simulado": 9230.29, "diferenca": 618.22}, {"codigo": "6", "baseline": 7984.9, "simulado": 8598.24, "diferenca": 613.34}], "origem_codigo": "llm", "comissao_periodo": [{"cargo": "100", "marca": "10", "data_fim": "2025-11-23", "pct_base": 2.5, "historico": [], "data_inicio": "2025-11-20", "pct_vigente": 2.5, "pct_com_campanha": 3.5}, {"cargo": "100", "marca": "10", "data_fim": "2025-11-28", "pct_base": 2.5, "historico": [{"nome": "Especificação nov/25, item 5f", "tipo": "ACRESCIMO", "autor": null, "versao": null, "data_fim": "2025-11-30", "pct_novo": null, "aprovador": null, "aprovada_em": null, "campanha_id": null, "data_inicio": "2025-11-24", "justificativa": "Black Friday: +1% nas vendas de 24 a 30/11, todas as marcas, exceto gerentes", "pct_acrescimo": 1.0}], "data_inicio": "2025-11-24", "pct_vigente": 3.5, "pct_com_campanha": 4.5}, {"cargo": "200", "marca": "10", "data_fim": "2025-11-23", "pct_base": 2.0, "historico": [], "data_inicio": "2025-11-20", "pct_vigente": 2.0, "pct_com_campanha": 3.0}, {"cargo": "200", "marca": "10", "data_fim": "2025-11-28", "pct_base": 2.0, "historico": [{"n