  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-aprovada', v_gabriela_id, 'usuario', NULL, NULL, $txt$Lana, qual foi a participação de cada cargo nas vendas da semana da Black Friday de 2025 (24/11 a 30/11)?$txt$, NULL, NULL, '2026-10-24 16:03:00+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-aprovada', v_gabriela_id, 'lana', NULL, NULL, $txt$Consultei as vendas de 24 a 30/11/2025 por cargo. O VENDEDOR LOJA (100) concentrou R$ 1.957.623,57 em 503 vendas (81,4% do total), o VENDEDOR BALCAO (200) somou R$ 350.137,84 (83 vendas), o ASSISTENTE DE VENDAS (300) somou R$ 65.848,53 (19 vendas) e os GERENTES DE LOJA (150) registraram R$ 32.515,99 em 116 vendas.$txt$, NULL, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "consultar_banco", "descricao": "Vendas por cargo na Black Friday 2025", "tabelas_acessadas": ["cargo", "funcionario_cargo", "venda"], "competencias": ["2025-11"], "filtros": "vendas entre 24/11/2025 e 30/11/2025 agrupadas por cargo", "sql_executado": "SELECT c.cod_cargo, c.descr_cargo, COUNT(*) AS qtd_vendas, ROUND(SUM(v.vlr_venda)::numeric, 2) AS total_valor FROM venda v JOIN funcionario_cargo fc ON fc.funcionario_id = v.funcionario_id AND fc.date_ref = date_trunc('month', v.date_ref)::date JOIN cargo c ON c.id = fc.cargo_id WHERE v.date_ref BETWEEN '2025-11-24' AND '2025-11-30' GROUP BY c.cod_cargo, c.descr_cargo ORDER BY c.cod_cargo LIMIT 50", "registros_retornados": 4, "dados": [{"cod_cargo": "100", "descr_cargo": "VENDEDOR LOJA", "qtd_vendas": 503, "total_valor": 1957623.57}, {"cod_cargo": "150", "descr_cargo": "GERENTE DE LOJA", "qtd_vendas": 116, "total_valor": 32515.99}, {"cod_cargo": "200", "descr_cargo": "VENDEDOR BALCAO", "qtd_vendas": 83, "total_valor": 350137.84}, {"cod_cargo": "300", "descr_cargo": "ASSISTENTE DE VENDAS", "qtd_vendas": 19, "total_valor": 65848.53}], "tempo_ms": 350, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-24 16:03:05+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-aprovada', v_gabriela_id, 'usuario', NULL, NULL, $txt$Vamos estruturar a campanha Black Friday 2025: de 24 a 30/11/2025, todas as marcas, para os cargos 100, 200 e 300, com acréscimo de 1,0% e meta de R$ 2.000.000,00.$txt$, NULL, NULL, '2026-10-24 16:06:10+00');
