  VALUES (v_camp_id, 1, v_sim_id, $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-aprovada", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-11-30", "data_inicio": "2025-11-24"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 1.5, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["ALL"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 2000000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Black Friday 2025 1,5% de 24 a 30/11/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $json${"meta": {"atingida": true, "diferenca": 406125.93, "meta_vendas": 2000000.0, "vendas_periodo": 2406125.93, "pct_atingimento": 120.31}, "codigo": "import pandas as pd\nimport numpy as np\nfrom datetime import datetime\n\nDATA_INICIO = \"2025-11-24\"\nDATA_FIM = \"2025-11-30\"\nPCT_ACRESCIMO = 1.5\nMARCAS_ALVO = [\"10\", \"20\", \"30\", \"40\", \"50\", \"60\"]\nCARGOS_ALVO = [\"100\", \"200\", \"300\"]\n\ndef aplicar_regra(bases, apuracao_base, competencias):\n    vendas = bases[\"vendas\"].copy()\n    \n    # Converter data_venda para datetime para filtragem correta por janela de datas\n    vendas[\"data_venda\"] = pd.to_datetime(vendas[\"data_venda\"])\n    dt_inicio = pd.to_datetime(DATA_INICIO)\n    dt_fim = pd.to_datetime(DATA_FIM)\n    \n    # Filtrar vendas na janela da campanha\n    mask_janela = (vendas[\"data_venda\"] >= dt_inicio) & (vendas[\"data_venda\"] <= dt_fim)\n    vendas_janela = vendas[mask_janela]\n    \n    # 1. Base para cargos normais (100, 200, 300, exceto gerente 150): vendas próprias na janela por matrícula, competencia, cod_marca, cod_cargo\n    vendas_normais = vendas_janela[~vendas_janela[\"cod_cargo\"].astype(str).isin([\"150\"])]\n    base_normais = vendas_normais.groupby(\n        [\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\"], as_index=False\n    )[\"vlr_venda\"].sum().rename(columns={\"vlr_venda\": \"base_periodo\"})\n    base_normais[\"tipo\"] = \"normal\"\n    \n    # 2. Base para gerentes (150): vendas TOTAIS da loja na janela por loja (e competencia)\n    # Gerente pega todas as vendas da loja no período, independente do cargo que vendeu\n    vendas_gerentes = vendas_janela.groupby(\n        [\"cod_loja\", \"competencia\"], as_index=False\n    )[\"vlr_venda\"].sum().rename(columns={\"vlr_venda\": \"base_loja_periodo\"})\n    \n    # Precisamos mapear cada gerente (matricula, competencia, cod_loja, cod_marca, cod_cargo) à sua loja na competência\n    rh_gerentes = bases[\"rh\"][bases[\"rh\"][\"cod_cargo\"].astype(str) == \"150\"][[\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"]].drop_duplicates()\n    \n    base_gerentes = rh_gerentes.merge(vendas_gerentes, on=[\"cod_loja\", \"competencia\"], how=\"left\")\n    base_gerentes[\"base_loja_periodo\"] = base_gerentes[\"base_loja_periodo\"].fillna(0.0)\n    base_gerentes = base_gerentes.rename(columns={\"base_loja_periodo\": \"base_periodo\"})\n    base_gerentes[\"tipo\"] = \"gerente\"\n    \n    # Unir as bases de cálculo do período\n    # Colunas comuns: matricula, competencia, cod_marca, cod_cargo, base_periodo\n    colunas_comuns = [\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\", \"base_periodo\"]\n    df_bases_periodo = pd.concat([\n        base_normais[colunas_comuns],\n        base_gerentes[colunas_comuns]\n    ], ignore_index=True)\n    \n    # Filtrar apenas marcas e cargos alvo\n    df_bases_periodo[\"cod_marca\"] = df_bases_periodo[\"cod_marca\"].astype(str)\n    df_bases_periodo[\"cod_cargo\"] = df_bases_periodo[\"cod_cargo\"].astype(str)\n    \n    mask_alvo = (\n        df_bases_periodo[\"cod_marca\"].isin(MARCAS_ALVO) &\n        df_bases_periodo[\"cod_cargo\"].isin(CARGOS_ALVO)\n    )\n    df_alvo = df_bases_periodo[mask_alvo].copy()\n    \n    # Calcular o delta da comissão: base_periodo * (PCT_ACRESCIMO / 100)\n    df_alvo[\"delta\"] = df_alvo[\"base_periodo\"] * (PCT_ACRESCIMO / 100.0)\n    \n    # Agrupar por matrícula e competência caso haja múltiplas linhas (ex: múltiplas marcas ou registros)\n    contribuicoes = df_alvo.groupby(\n        [\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\"], as_index=False\n    )[\"delta\"].sum()\n    \n    # Arredondar delta para 2 casas decimais\n    contribuicoes[\"delta\"] = contribuicoes[\"delta\"].round(2)\n    contribuicoes[\"elemento_ref\"] = \"pct_acrescimo\"\n    \n    # Remover deltas iguais a zero se houver\n    contribuicoes = contribuicoes[contribuicoes[\"delta\"] != 0].copy()\n    \n    # Preparar apuracao_simulada\n    apuracao_simulada = apuracao_base.copy()\n    apuracao_simulada[\"matricula\"] = apuracao_simulada[\"matricula\"].astype(str)\n    apuracao_simulada[\"competencia\"] = apuracao_simulada[\"competencia\"].astype(str)\n    \n    if not contribuicoes.empty:\n        delta_agregado = contribuicoes.groupby([\"matricula\", \"competencia\"], as_index=False)[\"delta\"].sum()\n        \n        apuracao_simulada = apuracao_simulada.merge(\n            delta_agregado, on=[\"matricula\", \"competencia\"], how=\"left\"\n        )\n        apuracao_simulada[\"delta\"] = apuracao_simulada[\"delta\"].fillna(0.0)\n        apuracao_simulada[\"comissao\"] = apuracao_simulada[\"comissao\"] + apuracao_simulada[\"delta\"]\n        apuracao_simulada[\"comissao\"] = apuracao_simulada[\"comissao\"].apply(lambda x: round(max(0.0, x), 2))\n        apuracao_simulada = apuracao_simulada.drop(columns=[\"delta\"])\n    else:\n        apuracao_simulada[\"comissao\"] = apuracao_simulada[\"comissao\"].apply(lambda x: round(max(0.0, x), 2))\n        \n    # Organizar colunas de contribuicoes exatamente como solicitado:\n    # matricula, competencia, cod_marca, cod_cargo, elemento_ref, delta\n    colunas_contribuicoes = [\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\", \"elemento_ref\", \"delta\"]\n    if contribuicoes.empty:\n        contribuicoes = pd.DataFrame(columns=colunas_contribuicoes)\n    else:\n        contribuicoes = contribuicoes[colunas_contribuicoes]\n        \n    return {\n        \"apuracao_simulada\": apuracao_simulada,\n        \"contribuicoes\": contribuicoes\n    }\n", "totais": {"baseline": 515738.39, "simulado": 551342.42, "diferenca": 35604.03, "diferenca_pct": 6.9}, "trilha": {"modelo": "gemini-3.5-flash-lite", "passos": [{"dados": null, "ordem": 1, "filtros": "vendas de 24/11/2025 a 30/11/2025; marcas 10, 20, 30, 40, 50, 60", "situacao": "SUCESSO", "tempo_ms": 124, "descricao": "Bases de nov/2025: 469 pessoas no RH, 721 vendas de 24/11 a 30/11, 24 linhas de % por marca e cargo", "ferramenta": "carregar_bases", "competencias": ["2025-11"], "mensagem_erro": null, "sql_executado": "SELECT f.matricula, to_char(fl.date_ref, 'YYYY-MM') AS competencia,\n       l.cod_loja, m.cod_marca, c.cod_cargo,\n       f.data_admissao, f.data_demissao\nFROM funcionario f\nJOIN funcionario_loja fl ON fl.funcionario_id = f.id\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = f.id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(fl.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT f.matricula, to_char(v.date_ref, 'YYYY-MM') AS competencia,\n       v.date_ref AS data_venda, v.vlr_venda::float8 AS vlr_venda,\n       l.cod_loja, m.cod_marca, c.cod_cargo\nFROM venda v\nJOIN funcionario f ON f.id = v.funcionario_id\nJOIN funcionario_loja fl ON fl.funcionario_id = v.funcionario_id\n     AND fl.date_ref = date_trunc('month', v.date_ref)::date\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = v.funcionario_id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(v.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT m.cod_marca, c.cod_cargo, mc.pct_comiss::float8 AS pct_comiss\nFROM marca_cargo mc\nJOIN marca m ON m.id = mc.marca_id\nJOIN cargo c ON c.id = mc.cargo_id\nWHERE mc.date_ref = (SELECT max(date_ref) FROM marca_cargo);", "tabelas_acessadas": ["cargo", "funcionario", "funcionario_cargo", "funcionario_loja", "loja", "marca", "marca_cargo", "venda"], "registros_retornados": 5491}, {"dados": null, "ordem": 2, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1215, "descricao": "Comissão atual (regras 5a a 5g): R$ 515.738,39", "ferramenta": "comissao_atual", "competencias": ["2025-11"], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 469}, {"dados": null, "ordem": 3, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 4207, "descricao": "Código gerado por gemini-3.5-flash-lite em 1 tentativa, conferido com o cálculo de referência", "ferramenta": "gerar_codigo", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 4, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 840, "descricao": "Código executado no sandbox", "ferramenta": "executar_sandbox", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 469}, {"dados": null, "ordem": 5, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 788, "descricao": "6 conferências passaram: colunas obrigatórias, mesmas pessoas e meses da comissão atual, sem comissão negativa, contribuições somam a diferença, escopo da regra, cálculo de referência", "ferramenta": "conferir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 6, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1479, "descricao": "Custo adicional de R$ 35.604,03", "ferramenta": "resumir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}], "campanhas": [{"nome": "Especificação nov/25, item 5f", "tipo": "ACRESCIMO", "autor": null, "versao": null, "data_fim": "2025-11-30", "pct_novo": null, "aprovador": null, "aprovada_em": null, "campanha_id": null, "data_inicio": "2025-11-24", "justificativa": "Black Friday: +1% nas vendas de 24 a 30/11, todas as marcas, exceto gerentes", "pct_acrescimo": 1.0}], "premissas": ["Gerentes (150) excluídos", "Cargos elegíveis: 100, 200, 300", "Marcas incluídas: 10, 20, 30, 40, 50, 60", "Período: de 24/11/2025 a 30/11/2025", "Acréscimo de comissão: +1.5%", "Simulação sobre vendas que já aconteceram: supõe que as pessoas venderiam o mesmo com a regra nova.", "A comparação com a comissão atual é o número mais confiável; o total absoluto é apurado por nós, não é a folha oficial.", "A comissão atual ainda não aplica proporcional de admissão/demissão nem férias e afastamentos."], "tentativas": 1}, "impacto": {"pessoas_total": 469, "maior_acrescimo": 418.22, "media_por_pessoa": 121.93, "pessoas_impactadas": 292}, "retorno": {"provisorio": true, "custo_pct_venda": 1.48, "custo_por_real_acima_meta": 0.09}, "rule_id": "rule-aprovada", "cenarios": [{"tipo": "sem_marca", "titulo": "Sem a marca Preto", "economia": 29006.65, "marcas_alvo": ["20", "30", "40", "50", "60"], "pct_acrescimo": 1.5, "cabe_no_orcamento": null, "custo_incremental": 6597.38}], "conflitos": [{"nome": "Campanha Virada de Novembro", "tipo": "ACRESCIMO", "autor": "Gabriela", "cargos": ["100", "200", "300"], "marcas": ["10", "20", "30", "40", "50", "60"], "status": "AGUARDANDO_APROVACAO", "versao": 1, "data_fim": "2025-11-28", "campanha_id": null, "data_inicio": "2025-11-20", "sobreposicao": {"data_fim": "2025-11-28", "data_inicio": "2025-11-24"}}], "orcamento": null, "por_cargo": [{"codigo": "100", "baseline": 291061.06, "simulado": 320425.31, "diferenca": 29364.25}, {"codigo": "150", "baseline": 155412.93, "simulado": 155412.93, "diferenca": 0.0}, {"codigo": "200", "baseline": 63708.26, "simulado": 68960.33, "diferenca": 5252.07}, {"codigo": "300", "baseline": 5556.14, "simulado": 6543.85, "diferenca": 987.71}], "por_marca": [{"codigo": "10", "baseline": 407902.53, "simulado": 436909.18, "diferenca": 29006.65}, {"codigo": "20", "baseline": 50758.07, "simulado": 53929.38, "diferenca": 3171.31}, {"codigo": "30", "baseline": 8641.86, "simulado": 9629.57, "diferenca": 987.71}, {"codigo": "40", "baseline": 43005.63, "simulado": 45022.13, "diferenca": 2016.5}, {"codigo": "50", "baseline": 2900.03, "simulado": 3257.63, "diferenca": 357.6}, {"codigo": "60", "baseline": 2530.27, "simulado": 2594.53, "diferenca": 64.26}], "ressalvas": ["Simulação sobre vendas que já aconteceram: supõe que as pessoas venderiam o mesmo com a regra nova.", "A comparação com a comissão atual é o número mais confiável; o total absoluto é apurado por nós, não é a folha oficial.", "A comissão atual ainda não aplica proporcional de admissão/demissão nem férias e afastamentos."], "explicacao": "No histórico, as vendas desse período somaram R$ 2.406.125,93, que representam 120% da meta de R$ 2.000.000,00, ficando 20% acima da meta, ou seja, R$ 406.125,93 acima. O custo extra da campanha ficou em R$ 35.604,03, o que dá 6,9% sobre a comissão atual de R$ 515.738,39, com 292 de 469 pessoas recebendo o acréscimo, em média R$ 121,93 cada, sendo o maior de R$ 418,22, a loja 35 com o maior custo extra de R$ 1.167,90, que representa 3,3% do total.\n\nA marca Preto pesa mais no custo extra, concentrando 81% do total, principalmente por causa do cargo de vendedor loja, que responde por 82% do acréscimo. Vale olhar o cenário calculado sem a marca Preto, que traz um acréscimo de 1,50% e um custo extra de R$ 6.597,38.", "observacao": "Resultado da IA conferido com o cálculo determinístico.", "tentativas": 1, "competencias": ["2025-11"], "maiores_lojas": [{"codigo": "35", "baseline": 11927.2, "simulado": 13095.1, "diferenca": 1167.9}, {"codigo": "26", "baseline": 10676.28, "simulado": 11662.58, "diferenca": 986.3}, {"codigo": "28", "baseline": 9155.82, "simulado": 10124.26, "diferenca": 968.44}, {"codigo": "24", "baseline": 8612.07, "simulado": 9539.39, "diferenca": 927.32}, {"codigo": "6", "baseline": 7984.9, "simulado": 8904.93, "diferenca": 920.03}], "origem_codigo": "llm", "comissao_periodo": [{"cargo": "100", "marca": "10", "data_fim": "2025-11-30", "pct_base": 2.5, "historico": [{"nome": "Especificação nov/25, item 5f", "tipo": "ACRESCIMO", "autor": null, "versao": null, "data_fim": "2025-11-30", "pct_novo": null, "aprovador": null, "aprovada_em": null, "campanha_id": null, "data_inicio": "2025-11-24", "justificativa": "Black Friday: +1% nas vendas de 24 a 30/11, todas as marcas, exceto gerentes", "pct_acrescimo": 1.0}], "data_inicio": "2025-11-24", "pct_vigente": 3.5, "pct_com_campanha": 5.0}, {"cargo": "200", "marca": "10", "data_fim": "2025-11-30", "pct_base": 2.0, "historico": [{"nome": "Especificação nov/25, item 5f", "tipo": "ACRESCIMO", "autor": null, "versao": null, "data_fim": "2025-11-30", "pct_novo": null, "a