  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-reprovada', v_gabriela_id, 'usuario', NULL, NULL, $txt$Lana, qual foi o faturamento das marcas Preto, Branco e Azul no início de agosto de 2025?$txt$, NULL, NULL, '2026-10-23 09:02:00+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-reprovada', v_gabriela_id, 'lana', NULL, NULL, $txt$Consultei os registros de 01/08/2025 para as marcas Preto, Branco e Azul. O total vendido somou R$ 9.816.543,35 em 4.722 vendas. A marca PRETO somou R$ 8.475.789,35 (4.015 vendas), BRANCO atingiu R$ 861.637,60 (440 vendas) e AZUL somou R$ 479.116,40 (267 vendas).$txt$, NULL, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "consultar_banco", "descricao": "Vendas marcas 10, 20 e 30 em ago/2025", "tabelas_acessadas": ["funcionario_loja", "loja", "marca", "venda"], "competencias": ["2025-08"], "filtros": "vendas de 01/08/2025 para marcas 10, 20 e 30", "sql_executado": "SELECT m.cod_marca, m.descr_marca, COUNT(*) AS qtd_vendas, ROUND(SUM(v.vlr_venda)::numeric, 2) AS total_valor FROM venda v JOIN funcionario_loja fl ON fl.funcionario_id = v.funcionario_id AND fl.date_ref = date_trunc('month', v.date_ref)::date JOIN loja l ON l.id = fl.loja_id JOIN marca m ON m.id = l.marca_id WHERE v.date_ref = '2025-08-01' AND m.cod_marca IN ('10', '20', '30') GROUP BY m.cod_marca, m.descr_marca ORDER BY m.cod_marca LIMIT 50", "registros_retornados": 3, "dados": [{"cod_marca": "10", "descr_marca": "PRETO", "qtd_vendas": 4015, "total_valor": 8475789.35}, {"cod_marca": "20", "descr_marca": "BRANCO", "qtd_vendas": 440, "total_valor": 861637.6}, {"cod_marca": "30", "descr_marca": "AZUL", "qtd_vendas": 267, "total_valor": 479116.4}], "tempo_ms": 310, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-23 09:02:05+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-reprovada', v_gabriela_id, 'usuario', NULL, NULL, $txt$Quero cadastrar uma campanha para a primeira quinzena de agosto (01 a 15/08/2025), com +1,5% para vendedores (cargos 100 e 200) nas marcas 10, 20 e 30.$txt$, NULL, NULL, '2026-10-23 09:05:10+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-reprovada', v_gabriela_id, 'lana', NULL, NULL, $txt$Registrei os parâmetros para as marcas 10, 20 e 30 de 01/08 a 15/08/2025 com 1,5% de acréscimo para os cargos 100 e 200. Falta definir a Meta Financeira da Campanha. Qual o valor?$txt$, $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-reprovada", "faltantes": ["meta_vendas"], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-08-15", "data_inicio": "2025-08-01"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 1.5, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["10", "20", "30"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": null, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Acréscimo Agosto 1,5% marcas 10, 20, 30", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "registrar_parametros_regra", "descricao": "Ficha da campanha registrada; falta informar: Meta Financeira da Campanha (R$)", "tabelas_acessadas": [], "competencias": ["2025-08"], "filtros": "marcas: 10, 20, 30; cargos: 100, 200; periodo: data_inicio: 2025-08-01; data_fim: 2025-08-15", "sql_executado": null, "registros_retornados": 0, "dados": null, "tempo_ms": 0, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-23 09:05:14+00');
