  INSERT INTO campanha_versao (campanha_id, numero, simulacao_id, regra, resultado, data_inicio, data_fim, ultima_mensagem_id, submetida_em)
  VALUES (v_camp_id, 1, v_sim_id, $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-reprovada", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-08-15", "data_inicio": "2025-08-01"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 1.5, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["10", "20", "30"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 15000000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Acréscimo de Agosto 1,5% de 01 a 15/08/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $json${"meta": {"atingida": false, "diferenca": -5183456.65, "meta_vendas": 15000000.0, "vendas_periodo": 9816543.35, "pct_atingimento": 65.44}, "codigo": "import pandas as pd\nimport numpy as np\nfrom datetime import datetime\n\nDATA_INICIO = \"2025-08-01\"\nDATA_FIM = \"2025-08-15\"\nPCT_ACRESCIMO = 1.5\nMARCAS_ALVO = [\"10\", \"20\", \"30\"]\nCARGOS_ALVO = [\"100\", \"200\"]\n\n\ndef aplicar_regra(bases, apuracao_base, competencias):\n    \"\"\"Aplica regra de campanha de comissionamento.\n\n    Adiciona um acréscimo percentual (pct_acrescimo) sobre as vendas do período\n    especificado para marcas e cargos alvo.\n    \"\"\"\n    vendas = bases[\"vendas\"]\n\n    dt_inicio = pd.to_datetime(DATA_INICIO)\n    dt_fim = pd.to_datetime(DATA_FIM)\n\n    # Filtrar vendas na janela de datas da campanha\n    mask_vendas = (vendas[\"data_venda\"] >= dt_inicio) & (\n        vendas[\"data_venda\"] <= dt_fim\n    )\n    vendas_periodo = vendas[mask_vendas].copy()\n\n    # Garantir tipos texto para os códigos\n    for df in [vendas_periodo, apuracao_base]:\n        for col in [\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"]:\n            if col in df.columns:\n                df[col] = df[col].astype(str)\n\n    # Dicionário para armazenar a base de cálculo da regra por (matricula, competencia)\n    bases_regra = {}\n\n    # Para cada competência e colaborador na apuração base, calcular a base da regra\n    # Cargos 100 e 200 recebem sobre suas próprias vendas na janela\n    # (Nota: a regra informada diz que cargos_alvo são [\"100\", \"200\"], logo aplicamos a lógica padrão de própria venda,\n    # mas caso houvesse gerente \"150\" nos cargos alvo, a lógica somaria a loja. Como os alvos são 100 e 200, filtramos por cargo e marca).\n\n    # Vamos agrupar as vendas do período por colaborador (matricula, competencia, cod_loja, cod_marca, cod_cargo)\n    # Filtrando pelas marcas_alvo e cargos_alvo\n    mask_alvo_vendas = vendas_periodo[\"cod_marca\"].isin(MARCAS_ALVO) & vendas_periodo[\n        \"cod_cargo\"\n    ].isin(CARGOS_ALVO)\n    vendas_filtradas = vendas_periodo[mask_alvo_vendas]\n\n    # Somar vendas por colaborador na janela\n    vendas_colab = (\n        vendas_filtradas.groupby(\n            [\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"],\n            as_index=False,\n        )[\"vlr_venda\"]\n        .sum()\n        .rename(columns={\"vlr_venda\": \"base_regra\"})\n    )\n\n    # Juntar com a apuração base para garantir que temos todas as linhas originais\n    apuracao_simulada = apuracao_base.copy()\n\n    # Merge para trazer a base_regra\n    apuracao_simulada = apuracao_simulada.merge(\n        vendas_colab,\n        on=[\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"],\n        how=\"left\",\n    )\n    apuracao_simulada[\"base_regra\"] = apuracao_simulada[\"base_regra\"].fillna(0.0)\n\n    # Calcular o delta: base_regra * (PCT_ACRESCIMO / 100)\n    apuracao_simulada[\"delta\"] = (\n        apuracao_simulada[\"base_regra\"] * PCT_ACRESCIMO / 100.0\n    )\n    apuracao_simulada[\"delta\"] = apuracao_simulada[\"delta\"].round(2)\n\n    # Criar a coluna comissão simulada\n    apuracao_simulada[\"comissao\"] = (\n        apuracao_simulada[\"comissao\"] + apuracao_simulada[\"delta\"]\n    )\n    apuracao_simulada[\"comissao\"] = apuracao_simulada[\"comissao\"].round(2)\n\n    # Garantir que comissão nunca fique negativa\n    apuracao_simulada[\"comissao\"] = apuracao_simulada[\"comissao\"].clip(lower=0.0)\n\n    # Recalcular delta real caso tenha tido arredondamento ou clip\n    # Como partimos de comissao_original + delta, o delta exato é a diferença final\n    # (ou mantemos o delta calculado se não houve restrição de menor que zero)\n\n    # Preparar DataFrame de contribuições (apenas onde delta != 0)\n    contribuicoes_df = apuracao_simulada[apuracao_simulada[\"delta\"] != 0.0].copy()\n    contribuicoes_df[\"elemento_ref\"] = \"pct_acrescimo\"\n\n    # Selecionar colunas exigidas para contribuicoes\n    colunas_contribuicoes = [\n        \"matricula\",\n        \"competencia\",\n        \"cod_marca\",\n        \"cod_cargo\",\n        \"elemento_ref\",\n        \"delta\",\n    ]\n    contribuicoes = contribuicoes_df[colunas_contribuicoes].copy()\n\n    # Limpar colunas temporárias de apuracao_simulada\n    apuracao_simulada = apuracao_simulada.drop(columns=[\"base_regra\", \"delta\"])\n\n    return {\n        \"apuracao_simulada\": apuracao_simulada,\n        \"contribuicoes\": contribuicoes,\n    }\n", "totais": {"baseline": 344985.4, "simulado": 482234.84, "diferenca": 137249.44, "diferenca_pct": 39.78}, "trilha": {"modelo": "gemini-3.5-flash-lite", "passos": [{"dados": null, "ordem": 1, "filtros": "vendas de 01/08/2025 a 15/08/2025; marcas 10, 20, 30", "situacao": "SUCESSO", "tempo_ms": 130, "descricao": "Bases de ago/2025: 465 pessoas no RH, 4722 vendas de 01/08 a 15/08, 24 linhas de % por marca e cargo", "ferramenta": "carregar_bases", "competencias": ["2025-08"], "mensagem_erro": null, "sql_executado": "SELECT f.matricula, to_char(fl.date_ref, 'YYYY-MM') AS competencia,\n       l.cod_loja, m.cod_marca, c.cod_cargo,\n       f.data_admissao, f.data_demissao\nFROM funcionario f\nJOIN funcionario_loja fl ON fl.funcionario_id = f.id\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = f.id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(fl.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT f.matricula, to_char(v.date_ref, 'YYYY-MM') AS competencia,\n       v.date_ref AS data_venda, v.vlr_venda::float8 AS vlr_venda,\n       l.cod_loja, m.cod_marca, c.cod_cargo\nFROM venda v\nJOIN funcionario f ON f.id = v.funcionario_id\nJOIN funcionario_loja fl ON fl.funcionario_id = v.funcionario_id\n     AND fl.date_ref = date_trunc('month', v.date_ref)::date\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = v.funcionario_id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(v.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT m.cod_marca, c.cod_cargo, mc.pct_comiss::float8 AS pct_comiss\nFROM marca_cargo mc\nJOIN marca m ON m.id = mc.marca_id\nJOIN cargo c ON c.id = mc.cargo_id\nWHERE mc.date_ref = (SELECT max(date_ref) FROM marca_cargo);", "tabelas_acessadas": ["cargo", "funcionario", "funcionario_cargo", "funcionario_loja", "loja", "marca", "marca_cargo", "venda"], "registros_retornados": 5471}, {"dados": null, "ordem": 2, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1071, "descricao": "Comissão atual (regras 5a a 5g): R$ 344.985,40", "ferramenta": "comissao_atual", "competencias": ["2025-08"], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 465}, {"dados": null, "ordem": 3, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 3947, "descricao": "Código gerado por gemini-3.5-flash-lite em 1 tentativa, conferido com o cálculo de referência", "ferramenta": "gerar_codigo", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 4, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 805, "descricao": "Código executado no sandbox", "ferramenta": "executar_sandbox", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 465}, {"dados": null, "ordem": 5, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 810, "descricao": "6 conferências passaram: colunas obrigatórias, mesmas pessoas e meses da comissão atual, sem comissão negativa, contribuições somam a diferença, escopo da regra, cálculo de referência", "ferramenta": "conferir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 6, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1384, "descricao": "Custo adicional de R$ 137.249,44", "ferramenta": "resumir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}], "campanhas": [], "premissas": ["Gerentes (150) excluídos", "Cargos elegíveis: 100, 200", "Marcas incluídas: 10, 20, 30", "Período: de 01/08/2025 a 15/08/2025", "Acréscimo de comissão: +1.5%", "Simulação sobre vendas que já aconteceram: supõe que as pessoas venderiam o mesmo com a regra nova.", "A comparação com a comissão atual é o número mais confiável; o total absoluto é apurado por nós, não é a folha oficial.", "A comissão atual ainda não aplica proporcional de admissão/demissão nem férias e afastamentos."], "tentativas": 1}, "impacto": {"pessoas_total": 465, "maior_acrescimo": 916.4, "media_por_pessoa": 393.26, "pessoas_impactadas": 349}, "retorno": {"provisorio": true, "custo_pct_venda": 1.4, "custo_por_real_acima_meta": null}, "rule_id": "rule-reprovada", "cenarios": [{"tipo": "sem_marca", "titulo": "Sem a marca Preto", "economia": 124534.67, "marcas_alvo": ["20", "30"], "pct_acrescimo": 1.5, "cabe_no_orcamento": null, "custo_incremental": 12714.77}], "conflitos": [], "orcamento": null, "por_cargo": [{"codigo": "100", "baseline": 208855.96, "simulado": 333390.63, "diferenca": 124534.67}, {"codigo": "150", "baseline": 97312.93, "simulado": 97312.93, "diferenca": 0.0}, {"codigo": "200", "baseline": 34382.51, "simulado": 47097.28, "diferenca": 12714.77}, {"codigo": "300", "baseline": 4434.0, "simulado": 4434.0, "diferenca": 0.0}], "por_marca": [{"codigo": "10", "baseline": 285174.17, "simulado": 409708.84, "diferenca": 124534.67}, {"codigo": "20", "baseline": 31476.55, "simulado": 44191.32, "diferenca": 12714.77}, {"codigo": "30", "baseline": 7999.4, "simulado": 7999.4, "diferenca": 0.0}, {"codigo": "40", "baseline": 17841.6, "simulado": 17841.6, "diferenca": 0.0}, {"codigo": "50", "baseline": 1298.23, "simulado": 1298.23, "diferenca": 0.0}, {"codigo": "60", "baseline": 1195.45, "simulado": 1195.45, "diferenca": 0.0}], "ressalvas": ["Simulação sobre vendas que já aconteceram: supõe que as pessoas venderiam o mesmo com a regra nova.", "A comparação com a comissão atual é o número mais confiável; o total absoluto é apurado por nós, não é a folha oficial.", "A comissão atual ainda não aplica proporcional de admissão/demissão nem férias e afastamentos."], "explicacao": "No histórico, as vendas desse período somaram R$ 9.816.543,35, 65% da meta de R$ 15.000.000,00 (35% abaixo da meta). São R$ 5.183.456,65 abaixo da meta. O custo extra da campanha é de R$ 137.249,44 (40% sobre a comissão atual de R$ 344.985,40). 349 de 465 pessoas recebem o acréscimo, em média R$ 393,26 cada (maior: R$ 916,40). A loja com maior custo extra é a loja 26, com R$ 3.945,80 (2,9% do total).\n\nA maior parte do custo extra vem da marca Preto (91% do total), puxado pelo cargo vendedor loja (91% do total). O cenário calculado sem a marca Preto traz um acréscimo de 1,50% e custo extra de R$ 12.714,77.", "observacao": "Resultado da IA conferido com o cálculo determinístico.", "tentativas": 1, "competencias": ["2025-08"], "maiores_lojas": [{"codigo": "26", "baseline": 9339.53, "simulado": 13285.33, "diferenca": 3945.8}, {"codigo": "14", "baseline": 6213.01, "simulado": 9940.81, "diferenca": 3727.8}, {"codigo": "28", "baseline": 8569.34, "simulado": 12238.96, "diferenca": 3669.62}, {"codigo": "17", "baseline": 7518.8, "simulado": 10720.18, "diferenca": 3201.38}, {"codigo": "35", "baseline": 7259.82, "simulado": 10368.17, "diferenca": 3108.35}], "origem_codigo": "llm", "comissao_periodo": [{"cargo": "100", "marca": "10", "data_fim": "2025-08-15", "pct_base": 2.5, "historico": [], "data_inicio": "2025-08-01", "pct_vigente": 2.5, "pct_com_campanha": 4.0}, {"cargo": "200", "marca": "10", "data_fim": "2025-08-15", "pct_base": 2.0, "historico": [], "data_inicio": "2025-08-01", "pct_vigente": 2.0, "pct_com_campanha": 3.5}, {"cargo": "100", "marca": "20", "data_fim": "2025-08-15", "pct_base": 3.0, "historico": [], "data_inicio": "2025-08-01", "pct_vigente": 3.0, "pct_com_campanha": 4.5}, {"cargo": "200", "marca": "20", "data_fim": "2025-08-15", "pct_base": 2.5, "historico": [], "data_inicio": "2025-08-01", "pct_vigente": 2.5, "pct_com_campanha": 4.0}, {"cargo": "100", "marca": "30", "data_fim": "2025-08-15", "pct_base": 2.0, "historico": [], "data_inicio": "2025-08-01", "pct_vigente": 2.0, "pct_com_campanha": 3.5}, {"cargo": "200", "marca": "30", "data_fim": "2025-08-15", "pct_base": 1.5, "historico": [], "data_inicio": "2025-08-01", "pct_vigente": 1.5, "pct_com_campanha": 3.0}]}$json$::jsonb, '2025-08-01', '2025-08-15', v_msg_id, '2026-10-23 09:30:00+00')
