  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-arquivada', v_gabriela_id, 'lana', NULL, NULL, $txt$Consultei o banco para setembro de 2025. As marcas Preto (10) e Branco (20) totalizaram R$ 8.758.508,15 em 4.470 vendas registradas: R$ 7.969.230,15 da PRETO (4.039 vendas) e R$ 789.278,00 da BRANCO (431 vendas).$txt$, NULL, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "consultar_banco", "descricao": "Vendas marcas 10 e 20 em set/2025", "tabelas_acessadas": ["funcionario_loja", "loja", "marca", "venda"], "competencias": ["2025-09"], "filtros": "vendas de 01/09/2025 para marcas 10 e 20", "sql_executado": "SELECT m.cod_marca, m.descr_marca, COUNT(*) AS qtd_vendas, ROUND(SUM(v.vlr_venda)::numeric, 2) AS total_valor FROM venda v JOIN funcionario_loja fl ON fl.funcionario_id = v.funcionario_id AND fl.date_ref = date_trunc('month', v.date_ref)::date JOIN loja l ON l.id = fl.loja_id JOIN marca m ON m.id = l.marca_id WHERE v.date_ref = '2025-09-01' AND m.cod_marca IN ('10', '20') GROUP BY m.cod_marca, m.descr_marca ORDER BY m.cod_marca LIMIT 50", "registros_retornados": 2, "dados": [{"cod_marca": "10", "descr_marca": "PRETO", "qtd_vendas": 4039, "total_valor": 7969230.15}, {"cod_marca": "20", "descr_marca": "BRANCO", "qtd_vendas": 431, "total_valor": 789278.0}], "tempo_ms": 330, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-20 09:02:05+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
