enta": "registrar_parametros_regra", "descricao": "Ficha da campanha registrada", "tabelas_acessadas": [], "competencias": ["2025-09"], "filtros": "marcas: 10, 20; cargos: 100, 200; pct: 1.0; meta: 1200000.00; periodo: 2025-09-01 a 2025-09-15", "sql_executado": null, "registros_retornados": 0, "dados": null, "tempo_ms": 0, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-20 09:05:04+00');
