enta": "registrar_parametros_regra", "descricao": "Ficha da campanha registrada", "tabelas_acessadas": [], "competencias": ["2025-09"], "filtros": "marcas: 10, 20; cargos: 100, 300; pct: 0.75; meta: 1200000.00; periodo: 2025-09-01 a 2025-09-15", "sql_executado": null, "registros_retornados": 0, "dados": null, "tempo_ms": 0, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-20 09:08:14+00');
  INSERT INTO simulacao (usuario_id, chat_id, campanha_id, status, etapa, ficha, resultado, modelo, tentativas, criada_em, concluida_em)
  VALUES (v_gabriela_id, 'demo-chat-arquivada', v_camp_id, 'CONCLUIDA', 'Concluída', $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-arquivada", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-09-15", "data_inicio": "2025-09-01"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 0.75, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["10", "20"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 1200000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Incentivo Setembro 0,75% de 01 a 15/09/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $json${"meta": {"atingida": true, "diferenca": 7558508.15, "meta_vendas": 1200000.0, "vendas_periodo": 8758508.15, "pct_atingimento": 729.88}, "codigo": "import pandas as pd\nimport numpy as np\nfrom datetime import datetime\n\nDATA_INICIO = \"2025-09-01\"\nDATA_FIM = \"2025-09-15\"\nPCT_ACRESCIMO = 0.75\nMARCAS_ALVO = [\"10\", \"20\"]\nCARGOS_ALVO = [\"100\", \"300\"]\nCOMPETENCIAS = [\"2025-09\"]\n\n\ndef aplicar_regra(bases, apuracao_base, competencias):\n    # Converter códigos para string para garantir comparação correta\n    vendas = bases[\"vendas\"].copy()\n    vendas[\"matricula\"] = vendas[\"matricula\"].astype(str)\n    vendas[\"cod_loja\"] = vendas[\"cod_loja\"].astype(str)\n    vendas[\"cod_marca\"] = vendas[\"cod_marca\"].astype(str)\n    vendas[\"cod_cargo\"] = vendas[\"cod_cargo\"].astype(str)\n    vendas[\"data_venda\"] = pd.to_datetime(vendas[\"data_venda\"])\n\n    dt_inicio = pd.to_datetime(DATA_INICIO)\n    dt_fim = pd.to_datetime(DATA_FIM)\n\n    # Filtrar vendas na janela da regra\n    vendas_janela = vendas[\n        (vendas[\"data_venda\"] >= dt_inicio) & (vendas[\"data_venda\"] <= dt_fim)\n    ]\n\n    apuracao_simulada = apuracao_base.copy()\n    apuracao_simulada[\"matricula\"] = apuracao_simulada[\"matricula\"].astype(str)\n    apuracao_simulada[\"competencia\"] = apuracao_simulada[\"competencia\"].astype(str)\n    apuracao_simulada[\"cod_loja\"] = apuracao_simulada[\"cod_loja\"].astype(str)\n    apuracao_simulada[\"cod_marca\"] = apuracao_simulada[\"cod_marca\"].astype(str)\n    apuracao_simulada[\"cod_cargo\"] = apuracao_simulada[\"cod_cargo\"].astype(str)\n\n    # Identificar quem é elegível:\n    # 1. Pertence à competência da regra\n    # 2. cod_marca em MARCAS_ALVO\n    # 3. cod_cargo em CARGOS_ALVO (Nota: Gerentes cod_cargo \"150\" não estão em CARGOS_ALVO, mas se estivessem, somariam a loja toda. Conforme regra, cargos_alvo são [\"100\", \"300\"])\n    mask_elegivel = (\n        apuracao_simulada[\"competencia\"].isin(COMPETENCIAS)\n        & apuracao_simulada[\"cod_marca\"].isin(MARCAS_ALVO)\n        & apuracao_simulada[\"cod_cargo\"].isin(CARGOS_ALVO)\n    )\n\n    deltas = []\n\n    for idx, row in apuracao_simulada[mask_elegivel].iterrows():\n        mat = row[\"matricula\"]\n        comp = row[\"competencia\"]\n        loja = row[\"cod_loja\"]\n        marca = row[\"cod_marca\"]\n        cargo = row[\"cod_cargo\"]\n\n        # Se for cargo gerente (\"150\"), a base é a loja toda. Como cargos_alvo é [\"100\", \"300\"],\n        0  # eles ganham sobre a própria venda. Mas mantemos a lógica robusta caso mude.\n        if cargo == \"150\":\n            vendas_base = vendas_janela[vendas_janela[\"cod_loja\"] == loja][\n                \"vlr_venda\"\n            ].sum()\n        else:\n            vendas_base = vendas_janela[\n                (vendas_janela[\"matricula\"] == mat)\n                & (vendas_janela[\"competencia\"] == comp)\n            ][\"vlr_venda\"].sum()\n\n        delta = round(vendas_base * (PCT_ACRESCIMO / 100.0), 2)\n        if delta > 0:\n            deltas.append(\n                {\n                    \"matricula\": mat,\n                    \"competencia\": comp,\n                    \"cod_marca\": marca,\n                    \"cod_cargo\": cargo,\n                    \"elemento_ref\": \"pct_acrescimo\",\n                    \"delta\": delta,\n                }\n            )\n\n    if deltas:\n        df_deltas = pd.DataFrame(deltas)\n        # Agrupar caso haja duplicidades (embora chave seja matricula/competencia)\n        df_deltas_agg = (\n            df_deltas.groupby(\n                [\n                    \"matricula\",\n                    \"competencia\",\n                    \"cod_marca\",\n                    \"cod_cargo\",\n                    \"elemento_ref\",\n                ],\n                as_index=False,\n            )[\"delta\"]\n            .sum()\n            .copy()\n        )\n        df_deltas_agg[\"delta\"] = df_deltas_agg[\"delta\"].round(2)\n\n        # Aplicar na apuração simulada\n        # Merge para somar o delta\n        apuracao_simulada = apuracao_simulada.merge(\n            df_deltas_agg[[\"matricula\", \"competencia\", \"delta\"]],\n            on=[\"matricula\", \"competencia\"],\n            how=\"left\",\n        )\n        apuracao_simulada[\"delta\"] = apuracao_simulada[\"delta\"].fillna(0.0)\n        apuracao_simulada[\"comissao\"] = (\n            apuracao_simulada[\"comissao\"] + apuracao_simulada[\"delta\"]\n        )\n        apuracao_simulada[\"comissao\"] = apuracao_simulada[\"comissao\"].apply(\n            lambda x: max(0.0, round(x, 2))\n        )\n        apuracao_simulada = apuracao_simulada.drop(columns=[\"delta\"])\n\n        contribuicoes = df_deltas_agg[df_deltas_agg[\"delta\"] != 0.0].copy()\n    else:\n        contribuicoes = pd.DataFrame(\n            columns=[\n                \"matricula\",\n                \"competencia\",\n                \"cod_marca\",\n                \"cod_cargo\",\n                \"elemento_ref\",\n                \"delta\",\n            ]\n        )\n\n    return {\n        \"apuracao_simulada\": apuracao_simulada,\n        \"contribuicoes\": contribuicoes,\n    }\n", "totais": {"baseline": 410519.22, "simulado": 469179.84, "diferenca": 58660.62, "diferenca_pct": 14.29}, "trilha": {"modelo": "gemini-3.5-flash-lite", "passos": [{"dados": null, "ordem": 1, "filtros": "vendas de 01/09/2025 a 15/09/2025; marcas 10, 20", "situacao": "SUCESSO", "tempo_ms": 122, "descricao": "Bases de set/2025: 467 pessoas no RH, 4470 vendas de 01/09 a 15/09, 24 linhas de % por marca e cargo", "ferramenta": "carregar_bases", "competencias": ["2025-09"], "mensagem_erro": null, "sql_executado": "SELECT f.matricula, to_char(fl.date_ref, 'YYYY-MM') AS competencia,\n       l.cod_loja, m.cod_marca, c.cod_cargo,\n       f.data_admissao, f.data_demissao\nFROM funcionario f\nJOIN funcionario_loja fl ON fl.funcionario_id = f.id\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = f.id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(fl.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT f.matricula, to_char(v.date_ref, 'YYYY-MM') AS competencia,\n       v.date_ref AS data_venda, v.vlr_venda::float8 AS vlr_venda,\n       l.cod_loja, m.cod_marca, c.cod_cargo\nFROM venda v\nJOIN funcionario f ON f.id = v.funcionario_id\nJOIN funcionario_loja fl ON fl.funcionario_id = v.funcionario_id\n     AND fl.date_ref = date_trunc('month', v.date_ref)::date\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = v.funcionario_id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(v.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT m.cod_marca, c.cod_cargo, mc.pct_comiss::float8 AS pct_comiss\nFROM marca_cargo mc\nJOIN marca m ON m.id = mc.marca_id\nJOIN cargo c ON c.id = mc.cargo_id\nWHERE mc.date_ref = (SELECT max(date_ref) FROM marca_cargo);", "tabelas_acessadas": ["cargo", "funcionario", "funcionario_cargo", "funcionario_loja", "loja", "marca", "marca_cargo", "venda"], "registros_retornados": 5485}, {"dados": null, "ordem": 2, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1137, "descricao": "Comissão atual (regras 5a a 5g): R$ 410.519,22", "ferramenta": "comissao_atual", "competencias": ["2025-09"], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 467}, {"dados": null, "ordem": 3, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 4023, "descricao": "Código gerado por gemini-3.5-flash-lite em 1 tentativa, conferido com o cálculo de referência", "ferramenta": "gerar_codigo", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 4, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1250, "descricao": "Código executado no sandbox", "ferramenta": "executar_sandbox", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 467}, {"dados": null, "ordem": 5, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 807, "descricao": "6 conferências passaram: colunas obrigatórias, mesmas pessoas e meses da comissão atual, sem comissão negativa, contribuições somam a diferença, escopo da regra, cálculo de referência", "ferramenta": "conferir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 6, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1633, "descricao": "Custo adicional de R$ 58.660,62", "ferramenta": "resumir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}], "campanhas": [{"nome": "Especificação set/25, item 3g", "tipo": "SUBSTITUICAO", "autor": null, "versao": null, "data_fim": "2025-09-30", "pct_novo": null, "aprovador": null, "aprovada_em": null, "campanha_id": null, "data_inicio": "2025-09-01", "justificativa": "Somente em set/25, a marca 10 usa a % da marca 20 em todos os cargos", "pct_acrescimo": null}], "premissas": ["Gerentes (150) excluídos", "Cargos elegíveis: 100, 300", "Marcas incluídas: 10, 20", "Período: de 01/09/2025 a 15/09/2025", "Acréscimo de comissão: +0.75%", "Simulação sobre vendas que já aconteceram: supõe que as pessoas venderiam o mesmo com a regra nova.", "A comparação com a comissão atual é o número mais confiável; o total absoluto é apurado por nós, não é a folha oficial.", "A comissão atual ainda não aplica proporcional de admissão/demissão nem férias e afastamentos."], "tentativas": 1}, "impacto": {"pessoas_total": 467, "maior_acrescimo": 385.25, "media_por_pessoa": 194.24, "pessoas_impactadas": 302}, "retorno": {"provisorio": true, "custo_pct_venda": 0.67, "custo_por_real_acima_meta": 0.01}, "rule_id": "rule-arquivada", "cenarios": [], "conflitos": [{"nome": "Especificação set/25, item 3g", "tipo": "SUBSTITUICAO", "autor": null, "cargos": ["100", "300"], "marcas": ["10"], "status": "APROVADA", "versao": null, "data_fim": "2025-09-30", "campanha_id": null, "data_inicio": "2025-09-01", "sobreposicao": {"data_fim": "2025-09-15", "data_inicio": "2025-09-01"}}], "orcamento": null, "por_cargo": [{"codigo": "100", "baseline": 235643.68, "simulado": 294304.3, "diferenca": 58660.62}, {"codigo": "150", "baseline": 136371.56, "simulado": 136371.56, "diferenca": 0.0}, {"codigo": "200", "baseline": 35389.5, "simulado": 35389.5, "diferenca": 0.0}, {"codigo": "300", "baseline": 3114.48, "simulado": 3114.48, "diferenca": 0.0}], "por_marca": [{"codigo": "10", "baseline": 348414.17, "simulado": 407074.79, "diferenca": 58660.62}, {"codigo": "20", "baseline": 26831.87, "simulado": 26831.87, "diferenca": 0.0}, {"codigo": "30", "baseline": 5276.47, "simulado": 5276.47, "diferenca": 0.0}, {"codigo": "40", "baseline": 26308.68, "simulado": 26308.68, "diferenca": 0.0}, {"codigo": "50", "baseline": 1464.76, "simulado": 1464.76, "diferenca": 0.0}, {"codigo": "60", "baseline": 2223.27, "simulado": 2223.27, "diferenca": 0.0}], "ressalvas": ["Simulação sobre vendas que já aconteceram: supõe que as pessoas venderiam o mesmo com a regra nova.", "A comparação com a comissão atual é o número mais confiável; o total absoluto é apurado por nós, não é a folha oficial.", "A comissão atual ainda não aplica proporcional de admissão/demissão nem férias e afastamentos."], "explicacao": "No histórico, as vendas desse período somaram R$ 8.758.508,15, que representam 730% da meta de R$ 1.200.000,00, ou seja, 630% acima da meta, com R$ 7.558.508,15 acima do previsto. O custo extra da campanha ficou em R$ 58.660,62, representando 14% sobre a comissão atual de R$ 410.519,22. Desse total, 302 de 467 pessoas recebem o acréscimo, com média de R$ 194,24 cada e o maior valor de R$ 385,25, sendo a loja 16 a que tem o maior custo extra, com R$ 2.248,04, que equivalem a 3,8% do total.\n\nToda a maior parte do custo extra e o cargo que mais recebe o acréscimo concentram-se na marca Preto, com 100% do total, e no vendedor loja, também com 100% do total. Podemos seguir com o cenário da loja 16, com um custo extra de R$ 2.248,04 e 3,8% do total.", "observacao": "Resultado da IA conferido com o cálculo determinístico.", "tentativas": 1, "competencias": ["2025-09"], "maiores_lojas": [{"codigo": "16", "baseline": 13501.02, "simulado": 15749.06, "diferenca": 2248.04}, {"codigo": "7", "baseline": 11974.91, "simulado": 13970.47, "diferenca": 1995.56}, {"codigo": "14", "baseline": 15566.8, "simulado": 17505.54, "diferenca": 1938.74}, {"codigo": "26", "baseline": 11348.21, "simulado": 13226.76, "diferenca": 1878.55}, {"codigo": "24", "baseline": 10331.8, "simulado": 12052.91, "diferenca": 1721.11}], "origem_codigo": "llm", "comissao_periodo": [{"cargo": "100", "marca": "10", "data_fim": "2025-09-15", "pct_base": 2.5, "historico": [{"nome": "Especificação set/25, item 3g", "tipo": "SUBSTITUICAO", "autor": null, "versao": null, "data_fim": "2025-09-30", "pct_novo": 3.0, "aprovador": null, "aprovada_em": null, "campanha_id": null, "data_inicio": "2025-09-01", "justificativa": "Somente em set/25, a marca 10 usa a % da marca 20 em todos os cargos", "pct_acrescimo": null}], "data_inicio": "2025-09-01", "pct_vigente": 3.0, "pct_com_campanha": 3.75}, {"cargo": "300", "marca": "10", "data_fim": "2025-09-15", "pct_base": 1.5, "historico": [{"nome": "Especificação set/25, item 3g", "tipo": "SUBSTITUICAO", "autor": null, "versao": null, "data_fim": "2025-09-30", "pct_novo": 2.0, "aprovador": null, "aprovada_em": null, "campanha_id": null, "data_inicio": "2025-09-01", "justificativa": "Somente em set/25, a marca 10 usa a % da marca 20 em todos os cargos", "pct_acrescimo": null}], "data_inicio": "2025-09-01", "pct_vigente": 2.0, "pct_com_campanha": 2.75}, {"cargo": "100", "marca": "20", "data_fim": "2025-09-15", "pct_base": 3.0, "historico": [], "data_inicio": "2025-09-01", "pct_vigente": 3.0, "pct_com_campanha": 3.75}, {"cargo": "300", "marca": "20", "data_fim": "2025-09-15", "pct_base": 2.0, "historico": [], "data_inicio": "2025-09-01", "pct_vigente": 2.0, "pct_com_campa