  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-duas-versoes', v_gabriela_id, 'lana', NULL, NULL, $txt$Ficha preenchida: +2,0% de 01 a 12/10/2025, todas as marcas, cargos 100, 200 e 300, meta de R$ 2.000.000,00. Tudo pronto para simulação.$txt$, $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-duas-v1", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-10-12", "data_inicio": "2025-10-01"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 2.0, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["ALL"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 2000000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Campanha Dia das Crianças v1 2,0% de 01 a 12/10/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "registrar_parametros_regra", "descricao": "Ficha da campanha registrada", "tabelas_acessadas": [], "competencias": ["2025-10"], "filtros": "marcas: ALL; cargos: 100, 200, 300; pct: 2.0; meta: 2000000.00; periodo: 2025-10-01 a 2025-10-12", "sql_executado": null, "registros_retornados": 0, "dados": null, "tempo_ms": 0, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-21 08:36:04+00');
  INSERT INTO simulacao (usuario_id, chat_id, campanha_id, status, etapa, ficha, resultado, modelo, tentativas, criada_em, concluida_em)
  VALUES (v_gabriela_id, 'demo-chat-duas-versoes', v_camp_id, 'CONCLUIDA', 'Concluída', $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-duas-v1", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-10-12", "data_inicio": "2025-10-01"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 2.0, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["ALL"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 2000000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Campanha Dia das Crianças v1 2,0% de 01 a 12/10/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $json${"meta": {"atingida": true, "diferenca": 7776559.06, "meta_vendas": 2000000.0, "vendas_periodo": 9776559.06, "pct_atingimento": 488.83}, "codigo": "import pandas as pd\nimport numpy as np\nfrom datetime import datetime\n\nDATA_INICIO = \"2025-10-01\"\nDATA_FIM = \"2025-10-12\"\nPCT_ACRESCIMO = 2.0\nMARCAS_ALVO = [\"10\", \"20\", \"30\", \"40\", \"50\", \"60\"]\nCARGOS_ALVO = [\"100\", \"200\", \"300\"]\nGERENTE_CARGO = \"150\"\n\ndef aplicar_regra(bases, apuracao_base, competencias):\n    rh = bases[\"rh\"]\n    vendas = bases[\"vendas\"]\n    \n    # Filtrar vendas no período da regra\n    dt_inicio = pd.to_datetime(DATA_INICIO)\n    dt_fim = pd.to_datetime(DATA_FIM)\n    \n    mask_vendas = (vendas[\"data_venda\"] >= dt_inicio) & (vendas[\"data_venda\"] <= dt_fim)\n    vendas_periodo = vendas[mask_vendas].copy()\n    \n    # Garantir tipos texto\n    for df in [rh, vendas_periodo, apuracao_base]:\n        for col in [\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"]:\n            if col in df.columns:\n                df[col] = df[col].astype(str)\n                \n    # Dicionário de loja por funcionário (usando rh e competência)\n    # Como rh tem uma linha por matrícula e competência, podemos mapear\n    rh_map = rh.set_index([\"matricula\", \"competencia\"])[[\"cod_loja\", \"cod_marca\", \"cod_cargo\"]].to_dict(\"index\")\n    \n    contribuicoes_list = []\n    apuracao_simulada = apuracao_base.copy()\n    \n    # Mapear índice para atualização rápida\n    apuracao_simulada[\"_idx\"] = apuracao_simulada.index\n    \n    # Para cada linha da apuração base, verificar se se enquadra na regra\n    # Regra: cargos_alvo (100, 200, 300) ganham pct_acrescimo sobre suas vendas no período\n    # Gerentes (150) não estão explicitamente na lista de cargos_alvo do JSON (\"cargos_alvo\": [\"100\", \"200\", \"300\"]),\n    # portanto apenas os cargos_alvo recebem o acréscimo sobre suas próprias vendas.\n    \n    # Vamos calcular a base de vendas no período para os cargos alvo\n    # Para cada linha em apuracao_base onde cod_cargo in CARGOS_ALVO e cod_marca in MARCAS_ALVO:\n    \n    # Otimização: calcular vendas por (matricula, competencia) no período\n    vendas_filtro = vendas_periodo[\n        vendas_periodo[\"cod_marca\"].isin(MARCAS_ALVO) &\n        vendas_periodo[\"cod_cargo\"].isin(CARGOS_ALVO)\n    ]\n    \n    vendas_agg = vendas_filtro.groupby([\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\"])[\"vlr_venda\"].sum().reset_index()\n    vendas_agg.rename(columns={\"vlr_venda\": \"vlr_venda_periodo\"}, inplace=True)\n    \n    # Mesclar com apuracao_simulada\n    merge_df = pd.merge(\n        apuracao_simulada,\n        vendas_agg,\n        on=[\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\"],\n        how=\"left\"\n    )\n    merge_df[\"vlr_venda_periodo\"] = merge_df[\"vlr_venda_periodo\"].fillna(0.0)\n    \n    # Filtrar quem é alvo\n    is_alvo = (\n        merge_df[\"cod_cargo\"].isin(CARGOS_ALVO) & \n        merge_df[\"cod_marca\"].isin(MARCAS_ALVO) &\n        (merge_df[\"vlr_venda_periodo\"] > 0)\n    )\n    \n    # Calcular delta: vlr_venda_periodo * (PCT_ACRESCIMO / 100)\n    delta_calculado = np.where(is_alvo, merge_df[\"vlr_venda_periodo\"] * (PCT_ACRESCIMO / 100.0), 0.0)\n    delta_arredondado = np.round(delta_calculado, 2)\n    \n    # Atualizar comissao\n    novas_comissoes = merge_df[\"comissao\"] + delta_arredondado\n    # Comissão nunca pode ficar negativa\n    novas_comissoes = np.maximum(novas_comissoes, 0.0)\n    # Recalcular delta real considerando o limite inferior de 0 se houver\n    delta_final = np.round(novas_comissoes - merge_df[\"comissao\"], 2)\n    \n    apuracao_simulada[\"comissao\"] = novas_comissoes\n    \n    # Montar contribuições\n    mask_delta = delta_final != 0.0\n    if mask_delta.any():\n        df_contrib = merge_df[mask_delta].copy()\n        df_contrib[\"delta\"] = delta_final[mask_delta]\n        df_contrib[\"elemento_ref\"] = \"pct_acrescimo\"\n        contribuicoes = df_contrib[[\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\", \"elemento_ref\", \"delta\"]].copy()\n    else:\n        contribuicoes = pd.DataFrame(columns=[\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\", \"elemento_ref\", \"delta\"])\n        \n    apuracao_simulada = apuracao_simulada.drop(columns=[\"_idx\"])\n    \n    return {\n        \"apuracao_simulada\": apuracao_simulada,\n        \"contribuicoes\": contribuicoes\n    }\n", "totais": {"baseline": 339947.97, "simulado": 533774.79, "diferenca": 193826.82, "diferenca_pct": 57.02}, "trilha": {"modelo": "gemini-3.5-flash-lite", "passos": [{"dados": null, "ordem": 1, "filtros": "vendas de 01/10/2025 a 12/10/2025; marcas 10, 20, 30, 40, 50, 60", "situacao": "SUCESSO", "tempo_ms": 131, "descricao": "Bases de out/2025: 460 pessoas no RH, 4999 vendas de 01/10 a 12/10, 24 linhas de % por marca e cargo", "ferramenta": "carregar_bases", "competencias": ["2025-10"], "mensagem_erro": null, "sql_executado": "SELECT f.matricula, to_char(fl.date_ref, 'YYYY-MM') AS competencia,\n       l.cod_loja, m.cod_marca, c.cod_cargo,\n       f.data_admissao, f.data_demissao\nFROM funcionario f\nJOIN funcionario_loja fl ON fl.funcionario_id = f.id\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = f.id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(fl.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT f.matricula, to_char(v.date_ref, 'YYYY-MM') AS competencia,\n       v.date_ref AS data_venda, v.vlr_venda::float8 AS vlr_venda,\n       l.cod_loja, m.cod_marca, c.cod_cargo\nFROM venda v\nJOIN funcionario f ON f.id = v.funcionario_id\nJOIN funcionario_loja fl ON fl.funcionario_id = v.funcionario_id\n     AND fl.date_ref = date_trunc('month', v.date_ref)::date\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = v.funcionario_id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(v.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT m.cod_marca, c.cod_cargo, mc.pct_comiss::float8 AS pct_comiss\nFROM marca_cargo mc\nJOIN marca m ON m.id = mc.marca_id\nJOIN cargo c ON c.id = mc.cargo_id\nWHERE mc.date_ref = (SELECT max(date_ref) FROM marca_cargo);", "tabelas_acessadas": ["cargo", "funcionario", "funcionario_cargo", "funcionario_loja", "loja", "marca", "marca_cargo", "venda"], "registros_retornados": 5483}, {"dados": null, "ordem": 2, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1086, "descricao": "Comissão atual (regras 5a a 5g): R$ 339.947,97", "ferramenta": "comissao_atual", "competencias": ["2025-10"], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 460}, {"dados": null, "ordem": 3, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 3806, "descricao": "Código gerado por gemini-3.5-flash-lite em 1 tentativa, conferido com o cálculo de referência", "ferramenta": "gerar_codigo", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 4, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 823, "descricao": "Código executado no sandbox", "ferramenta": "executar_sandbox", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 460}, {"dados": null, "ordem": 5, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 791, "descricao": "6 conferências passaram: colunas obrigatórias, mesmas pessoas e meses da comissão atual, sem comissão negativa, contribuições somam a diferença, escopo da regra, cálculo de referência", "ferramenta": "conferir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 6, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1308, "descricao": "Custo adicional de R$ 193.826,82", "ferramenta": "resumir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}], "campanhas": [{"nome": "Especificação out/25, item 4g"