  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-duas-versoes', v_gabriela_id, 'usuario', NULL, NULL, $txt$Lana, o Sérgio reprovou apontando que 2,0% ficou alto demais e sugeriu 1,0% ou focar nas marcas de maior margem. Vamos ajustar a v2 para 1,0% de acréscimo, limitando às marcas 10, 20, 30 e 40, apenas para vendedores (cargos 100 e 200), e subindo a meta para R$ 2.500.000,00.$txt$, NULL, NULL, '2026-10-21 14:15:00+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-duas-versoes', v_gabriela_id, 'lana', NULL, NULL, $txt$Excelente ajuste para adequar ao orçamento. Registrei os novos parâmetros da v2: 01 a 12/10/2025, marcas 10, 20, 30 e 40, cargos 100 e 200, acréscimo de 1,0% e meta de R$ 2.500.000,00.$txt$, $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-duas-v2", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-10-12", "data_inicio": "2025-10-01"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 1.0, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["10", "20", "30", "40"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 2500000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Campanha Dia das Crianças v2 1,0% de 01 a 12/10/2025 marcas 10,20,30,40", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "registrar_parametros_regra", "descricao": "Ficha da campanha registrada", "tabelas_acessadas": [], "competencias": ["2025-10"], "filtros": "marcas: 10, 20, 30, 40; cargos: 100, 200; pct: 1.0; meta: 2500000.00; periodo: 2025-10-01 a 2025-10-12", "sql_executado": null, "registros_retornados": 0, "dados": null, "tempo_ms": 0, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-21 14:15:05+00');
  INSERT INTO simulacao (usuario_id, chat_id, campanha_id, status, etapa, ficha, resultado, modelo, tentativas, criada_em, concluida_em)
  VALUES (v_gabriela_id, 'demo-chat-duas-versoes', v_camp_id, 'CONCLUIDA', 'Concluída', $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-duas-v2", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-10-12", "data_inicio": "2025-10-01"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 1.0, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["10", "20", "30", "40"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 2500000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Campanha Dia das Crianças v2 1,0% de 01 a 12/10/2025 marcas 10,20,30,40", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $json${"meta": {"atingida": true, "diferenca": 7212642.06, "meta_vendas": 2500000.0, "vendas_periodo": 9712642.06, "pct_atingimento": 388.51}, "codigo": "import pandas as pd\n\n# Gerado pelo modelo fixo (plano B, sem LLM): acréscimo de % em janela de datas.\nDATA_INICIO = pd.Timestamp(\"2025-10-01\")\nDATA_FIM = pd.Timestamp(\"2025-10-12\")\nPCT_ACRESCIMO = 1.0\nMARCAS_ALVO = ['10', '20', '30', '40']\nCARGOS_ALVO = ['100', '200']\nCARGO_GERENTE = \"150\"\nELEMENTO = \"pct_acrescimo\"\n\n\ndef _vendas_na_janela(vendas):\n    dentro = (vendas[\"data_venda\"] >= DATA_INICIO) & (vendas[\"data_venda\"] <= DATA_FIM)\n    return vendas[dentro]\n\n\ndef _base_na_janela(apuracao, vendas):\n    por_matricula = vendas.groupby([\"matricula\", \"competencia\"], as_index=False)[\"vlr_venda\"].sum()\n    por_loja = vendas.groupby([\"cod_loja\", \"competencia\"], as_index=False)[\"vlr_venda\"].sum()\n    base = apuracao.merge(por_matricula, on=[\"matricula\", \"competencia\"], how=\"left\")\n    base = base.merge(por_loja, on=[\"cod_loja\", \"competencia\"], how=\"left\", suffixes=(\"\", \"_loja\"))\n    base = base.fillna({\"vlr_venda\": 0.0, \"vlr_venda_loja\": 0.0})\n    eh_gerente = base[\"cod_cargo\"] == CARGO_GERENTE\n    return base[\"vlr_venda_loja\"].where(eh_gerente, base[\"vlr_venda\"])\n\n\ndef aplicar_regra(bases, apuracao_base, competencias):\n    simulada = apuracao_base.copy()\n    elegivel = simulada[\"cod_marca\"].isin(MARCAS_ALVO) & simulada[\"cod_cargo\"].isin(CARGOS_ALVO)\n    base_janela = _base_na_janela(simulada, _vendas_na_janela(bases[\"vendas\"]))\n    delta = (base_janela * PCT_ACRESCIMO / 100).round(2).where(elegivel, 0.0)\n    simulada[\"comissao\"] = (simulada[\"comissao\"] + delta).round(2)\n    contribuicoes = simulada[[\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\"]].copy()\n    contribuicoes[\"elemento_ref\"] = ELEMENTO\n    contribuicoes[\"delta\"] = delta\n    contribuicoes = contribuicoes[contribuicoes[\"delta\"] != 0.0]\n    return {\"apuracao_simulada\": simulada, \"contribuicoes\": contribuicoes}\n", "totais": {"baseline": 339947.97, "simulado": 432915.49, "diferenca": 92967.52, "diferenca_pct": 27.35}, "trilha": {"modelo": "gemini-3.5-flash-lite", "passos": [{"dados": null, "ordem": 1, "filtros": "vendas de 01/10/2025 a 12/10/2025; marcas 10, 20, 30, 40", "situacao": "SUCESSO", "tempo_ms": 130, "descricao": "Bases de out/2025: 460 pessoas no RH, 4966 vendas de 01/10 a 12/10, 24 linhas de % por marca e cargo", "ferramenta": "carregar_bases", "competencias": ["2025-10"], "mensagem_erro": null, "sql_executado": "SELECT f.matricula, to_char(fl.date_ref, 'YYYY-MM') AS competencia,\n       l.cod_loja, m.cod_marca, c.cod_cargo,\n       f.data_admissao, f.data_demissao\nFROM funcionario f\nJOIN funcionario_loja fl ON fl.funcionario_id = f.id\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = f.id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(fl.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT f.matricula, to_char(v.date_ref, 'YYYY-MM') AS competencia,\n       v.date_ref AS data_venda, v.vlr_venda::float8 AS vlr_venda,\n       l.cod_loja, m.cod_marca, c.cod_cargo\nFROM venda v\nJOIN funcionario f ON f.id = v.funcionario_id\nJOIN funcionario_loja fl ON fl.funcionario_id = v.funcionario_id\n     AND fl.date_ref = date_trunc('month', v.date_ref)::date\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = v.funcionario_id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(v.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT m.cod_marca, c.cod_cargo, mc.pct_comiss::float8 AS pct_comiss\nFROM marca_cargo mc\nJOIN marca m ON m.id = mc.marca_id\nJOIN cargo c ON c.id = mc.cargo_id\nWHERE mc.date_ref = (SELECT max(date_ref) FROM marca_cargo);", "tabelas_acessadas": ["cargo", "funcionario", "funcionario_cargo", "funcionario_loja", "loja", "marca", "marca_cargo", "venda"], "registros_retornados": 5483}, {"dados": null, "ordem": 2, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1066, "descricao": "Comissão atual (regras 5a a 5g): R$ 339.947,97", "ferramenta": "comissao_atual", "competencias": ["2025-10"], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 460}, {"dados": null, "ordem": 3, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 6976, "descricao": "O código gerado por gemini-3.5-flash-lite divergiu do cálculo de referência em 2 tentativas; valeu o cálculo de referência", "ferramenta": "gerar_codigo", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 4, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 824, "descricao": "Código executado no sandbox", "ferramenta": "executar_sandbox", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 460}, {"dados": null, "ordem": 5, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 793, "descricao": "5 conferências passaram: colunas obrigatórias, mesmas pessoas e meses da comissão atual, sem comissão negativa, contribuições somam a diferença, escopo da regra", "ferramenta": "conferir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 6, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 2397, "descricao": "Custo adicional de R$ 92.967,52", "ferramenta": "resumir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}], "campanhas": [{"nome": "Especificação out/25, item 4g", "tipo": "ACRESCIMO", "autor": null, "versao": null, "data_fim": "2025-10-31", "pct_novo": null, "aprovador": null, "aprovada_em": null, "campanha_id": null, "data_inicio": "2025-10-01", "justificativa": "Marca 30: +0,5% em todas as vendas de out/25, exceto gerentes", "pct_acrescimo": 0.5}], "premissas": ["Gerentes (150) excluídos", "Cargos elegíveis: 100, 200", "Marcas incluídas: 10, 20, 30, 40", "Período: de 01/10/2025 a 12/10/2025", "Acréscimo de comissão: +1.0%", "Simulação sobre vendas que já aconteceram: supõe que as pessoas venderiam o mesmo com a regra nova.", "A comparação com a comissão atual é o número mais confiável; o total absoluto é apurado por nós, não é a folha oficial.", "A comissão atual ainda não aplica proporcional de admissão/demissão nem férias e afastamentos."], "tentativas": 2}, "impacto": {"pessoas_total": 460, "maior_acrescimo": 503.51, "media_por_pessoa": 254.01, "pessoas_impactadas": 366}, "retorno": {"provisorio": true, "custo_pct_venda": 0.96, "custo_por_real_acima_meta": 0.01}, "rule_id": "rule-duas-v2", "cenarios": [{"tipo": "sem_marca", "titulo": "Sem a marca Preto", "economia": 78659.35, "marcas_alvo": ["20", "30", "40"], "pct_acrescimo": 1.0, "cabe_no_orcamento": null, "custo_incremental": 14308.17}], "conflitos": [{"nome": "Especificação out/25, item 4g", "tipo": "ACRESCIMO", "autor": null, "cargos": ["100", "200"], "marcas": ["30"], "status": "APROVADA", "versao": null, "data_fim": "2025-10-31", "campanha_id": null, "data_inicio": "2025-10-01", "sobreposicao": {"data_fim": "2025-10-12", "data_inicio": "2025-10-01"}}], "orcamento": null, "por_cargo": [{"codigo": "100", "baseline": 197623.11, "simulado": 276312.39, "diferenca": 78689.28}, {"codigo": "150", "baseline": 98492.53, "simulado": 98492.53, "diferenca": 0.0}, {"codigo": "200", "baseline": 38872.22, "simulado": 53150.46, "diferenca": 14278.24}, {"codigo": "300", "baseline": 4960.11, "simulado": 4960.11, "diferenca": 0.0}], "por_marca": [{"codigo": "10", "baseline": 272626.08, "simulado": 351285.43, "diferenca": 78659.35}, {"codigo": "20", "baseline": 34520.62, "simulado": 43841.86, "diferenca": 9321.24}, {"codigo": "30", "baseline": 5596.16, "simulado": 5626.09, "diferenca": 29.93}, {"codigo": "40", "baseline": 24828.4, "simulado": 29785.4, "diferenca": 4957.0}, {"codigo": "50", "baseline": 1259.83, "simulado": 1259.83, "diferenca": 0.0}, {"codigo": "60", "baseline": 1116.88, "simulado": 1116.88, "diferenca": 0.0}], "ressalvas": ["Simulação sobre vendas que já aconteceram: supõe que as pessoas venderiam o mesmo com a regra nova.", "A comparação com a comissão atual é o número mais confiável; o total absoluto é apurado por nós, não é a folha oficial.", "A comissão atual ainda não aplica proporcional de admissão/demissão nem férias e afastamentos."], "explicacao": "No histórico, as vendas desse período somaram R$ 9.712.642,06, 389% da meta de R$ 2.500.000,00 (289% acima da meta). São R$ 7.212.642,06 acima da meta. O custo extra da campanha é de R$ 92.967,52, o que representa 27% sobre a comissão atual de R$ 339.947,97. Dessas, 366 de 460 pessoas recebem o acréscimo, em média R$ 254,01 cada, sendo a maior de R$ 503,51. A loja com maior custo extra é a loja 26, com R$ 2.747,91, que representa 3,0% do total.\n\nA maior parte do custo extra vem da marca Preto, concentrada no cargo de vendedor loja, ambos com 85% do total. O cenário calculado 'Sem a marca Preto' resulta em um acréscimo de 1,00% e custo extra de R$ 14.308,17.", "observacao": "O código da IA divergiu do cálculo determinístico em todas as tentativas; o resultado mostrado é o do cálculo determinístico. Último erro: CodigoInvalidoError: Código gerado não é Python válido: linha 25: unexpected indent", "tentativas": 2, "competencias": ["2025-10"], "maiores_lojas": [{"codigo": "26", "baseline": 9631.61, "simulado": 12379.52, "diferenca": 2747.91}, {"codigo": "7", "baseline": 8860.12, "simulado": 11388.94, "diferenca": 2528.82}, {"codigo": "4", "baseline": 5210.74, "simulado": 7295.04, "diferenca": 2084.3}, {"codigo": "13", "baseline": 6619.36, "simulado": 8499.46, "diferenca": 1880.1}, {"codigo": "17", "baseline": 6518.79, "simulado": 8378.11, "diferenca": 1859.32}], "origem_codigo": "modelo", "comissao_periodo": [{"cargo": "100", "marca": "10", "data_fim": "2025-10-12", "pct_base": 2.5, "historico": [], "data_inicio": "2025-10-01", "pct_vigente": 2.5, "pct_com_campanha": 3.5}, {