  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-supervisor-sergio', v_sergio_id, 'usuario', NULL, NULL, $txt$Lana, qual é o quadro de funcionários ativos por cargo no mês de dezembro de 2025?$txt$, NULL, NULL, '2026-10-25 08:02:00+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-supervisor-sergio', v_sergio_id, 'lana', NULL, NULL, $txt$Consultei o quadro de pessoal para dezembro de 2025. São 467 colaboradores ativos distribuídos em: 300 VENDEDORES LOJA (100), 73 GERENTES DE LOJA (150), 73 VENDEDORES BALCAO (200) e 21 ASSISTENTES DE VENDAS (300).$txt$, NULL, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "consultar_banco", "descricao": "Quadro de funcionários em dez/2025", "tabelas_acessadas": ["cargo", "funcionario_cargo"], "competencias": ["2025-12"], "filtros": "colaboradores ativos em 01/12/2025 agrupados por cargo", "sql_executado": "SELECT c.cod_cargo, c.descr_cargo, COUNT(DISTINCT fc.funcionario_id) AS total_funcionarios FROM funcionario_cargo fc JOIN cargo c ON c.id = fc.cargo_id WHERE fc.date_ref = '2025-12-01' GROUP BY c.cod_cargo, c.descr_cargo ORDER BY c.cod_cargo LIMIT 50", "registros_retornados": 4, "dados": [{"cod_cargo": "100", "descr_cargo": "VENDEDOR LOJA", "total_funcionarios": 300}, {"cod_cargo": "150", "descr_cargo": "GERENTE DE LOJA", "total_funcionarios": 73}, {"cod_cargo": "200", "descr_cargo": "VENDEDOR BALCAO", "total_funcionarios": 73}, {"cod_cargo": "300", "descr_cargo": "ASSISTENTE DE VENDAS", "total_funcionarios": 21}], "tempo_ms": 280, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-25 08:02:05+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-supervisor-sergio', v_sergio_id, 'usuario', NULL, NULL, $txt$Como supervisor, quero lançar um incentivo de Natal antecipado: de 01 a 14/12/2025, todas as marcas, para os cargos 100, 200 e 300, com acréscimo moderado de 0,5%.$txt$, NULL, NULL, '2026-10-25 08:05:00+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-supervisor-sergio', v_sergio_id, 'lana', NULL, NULL, $txt$Registrei os parâmetros para todas as marcas de 01 a 14/12/2025 com +0,5% para vendedores e assistentes (394 elegíveis). Falta estipular a Meta Financeira da Campanha. Qual o valor desejado?$txt$, $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-sergio", "faltantes": ["meta_vendas"], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-12-14", "data_inicio": "2025-12-01"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 0.5, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["ALL"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": null, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Incentivo Natal Antecipado 0,5% de 01 a 14/12/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "registrar_parametros_regra", "descricao": "Ficha da campanha registrada; falta informar: Meta Financeira da Campanha (R$)", "tabelas_acessadas": [], "competencias": ["2025-12"], "filtros": "marcas: ALL; cargos: 100, 200, 300; periodo: data_inicio: 2025-12-01; data_fim: 2025-12-14", "sql_executado": null, "registros_retornados": 0, "dados": null, "tempo_ms": 0, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-25 08:05:04+00');
