  VALUES ('demo-chat-supervisor-sergio', v_sergio_id, 'lana', NULL, NULL, $txt$Meta de R$ 3.000.000,00 registrada com sucesso! A ficha está completa e pronta para rodar a simulação.$txt$, $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-sergio", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-12-14", "data_inicio": "2025-12-01"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 0.5, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["ALL"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 3000000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Incentivo Natal Antecipado 0,5% de 01 a 14/12/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "registrar_parametros_regra", "descricao": "Ficha da campanha registrada", "tabelas_acessadas": [], "competencias": ["2025-12"], "filtros": "marcas: ALL; cargos: 100, 200, 300; meta: 3000000.00; periodo: 2025-12-01 a 2025-12-14", "sql_executado": null, "registros_retornados": 0, "dados": null, "tempo_ms": 0, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-25 08:07:34+00');
  INSERT INTO simulacao (usuario_id, chat_id, campanha_id, status, etapa, ficha, resultado, modelo, tentativas, criada_em, concluida_em)
  VALUES (v_sergio_id, 'demo-chat-supervisor-sergio', v_camp_id, 'CONCLUIDA', 'Concluída', $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-sergio", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-12-14", "data_inicio": "2025-12-01"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 0.5, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["ALL"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 3000000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Incentivo Natal Antecipado 0,5% de 01 a 14/12/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $json${"meta": {"atingida": true, "diferenca": 10187602.83, "meta_vendas": 3000000.0, "vendas_periodo": 13187602.83, "pct_atingimento": 439.59}, "codigo": "import pandas as pd\nimport numpy as np\nfrom datetime import datetime\n\nDATA_INICIO = \"2025-12-01\"\nDATA_FIM = \"2025-12-14\"\nPCT_ACRESCIMO = 0.5\nMARCAS_ALVO = [\"10\", \"20\", \"30\", \"40\", \"50\", \"60\"]\nCARGOS_ALVO = [\"100\", \"200\", \"300\"]\n\ndef aplicar_regra(bases, apuracao_base, competencias):\n    rh = bases[\"rh\"]\n    vendas = bases[\"vendas\"]\n    \n    # Filtrar vendas no período da regra\n    dt_inicio = pd.to_datetime(DATA_INICIO)\n    dt_fim = pd.to_datetime(DATA_FIM)\n    \n    vendas_periodo = vendas[\n        (vendas[\"data_venda\"] >= dt_inicio) & \n        (vendas[\"data_venda\"] <= dt_fim)\n    ]\n    \n    # Base de cálculo no período da regra para cada matrícula\n    # Se for gerente (cod_cargo == \"150\"), a base é a soma das vendas da loja inteira no período\n    # Para os demais cargos alvo (100, 200, 300), a base é a venda própria do funcionário no período\n    \n    # 1. Vendas próprias no período por matrícula\n    vendas_proprias = vendas_periodo.groupby([\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"], as_index=False)[\"vlr_venda\"].sum()\n    vendas_proprias = vendas_proprias.rename(columns={\"vlr_venda\": \"base_periodo\"})\n    \n    # 2. Vendas totais da loja no período (para gerentes)\n    vendas_loja = vendas_periodo.groupby([\"competencia\", \"cod_loja\"], as_index=False)[\"vlr_venda\"].sum()\n    vendas_loja = vendas_loja.rename(columns={\"vlr_venda\": \"base_loja_periodo\"})\n    \n    # Mesclar com apuracao_base para garantir o escopo correto e identificar gerentes\n    apuracao_simulada = apuracao_base.copy()\n    \n    # Identificar quais registros são elegíveis\n    elegivel = (\n        apuracao_simulada[\"cod_marca\"].isin(MARCAS_ALVO) & \n        apuracao_simulada[\"cod_cargo\"].isin(CARGOS_ALVO) &\n        apuracao_simulada[\"competencia\"].isin(competencias)\n    )\n    \n    # Mapear bases do período para a apuração\n    # Primeiro, juntamos vendas próprias\n    df_trab = apuracao_simulada[[\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"]].copy()\n    df_trab = df_trab.merge(\n        vendas_proprias[[\"matricula\", \"competencia\", \"base_periodo\"]],\n        on=[\"matricula\", \"competencia\"],\n        how=\"left\"\n    )\n    df_trab[\"base_periodo\"] = df_trab[\"base_periodo\"].fillna(0.0)\n    \n    # Juntar vendas da loja\n    df_trab = df_trab.merge(\n        vendas_loja[[\"competencia\", \"cod_loja\", \"base_loja_periodo\"]],\n        on=[\"competencia\", \"cod_loja\"],\n        how=\"left\"\n    )\n    df_trab[\"base_loja_periodo\"] = df_trab[\"base_loja_periodo\"].fillna(0.0)\n    \n    # Calcular base específica para o acréscimo\n    # Se cargo for 150 (gerente), a regra diz que acréscimo para gerentes incide sobre a venda da loja,\n    # MAS o cargo 150 NÃO está em CARGOS_ALVO (\"100\", \"200\", \"300\"). Portanto, cargo 150 NUNCA recebe acréscimo.\n    # Logo, apenas cargos 100, 200, 300 recebem, e para eles a base é a venda própria.\n    \n    delta = np.where(\n        elegivel,\n        df_trab[\"base_periodo\"] * (PCT_ACRESCIMO / 100.0),\n        0.0\n    )\n    delta = np.round(delta, 2)\n    \n    apuracao_simulada[\"comissao\"] = np.round(apuracao_simulada[\"comissao\"] + delta, 2)\n    \n    # Montar o DataFrame de contribuicoes apenas com quem teve delta != 0\n    df_trab[\"delta\"] = delta\n    mask_contribuicoes = (df_trab[\"delta\"] != 0) & (df_trab[\"competencia\"].isin(competencias))\n    \n    contribuicoes = df_trab.loc[mask_contribuicoes, [\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\", \"delta\"]].copy()\n    contribuicoes[\"elemento_ref\"] = \"pct_acrescimo\"\n    contribuicoes = contribuicoes[[\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\", \"elemento_ref\", \"delta\"]]\n    \n    return {\n        \"apuracao_simulada\": apuracao_simulada,\n        \"contribuicoes\": contribuicoes\n    }\n", "totais": {"baseline": 456827.22, "simulado": 521476.85, "diferenca": 64649.63, "diferenca_pct": 14.15}, "trilha": {"modelo": "gemini-3.5-flash-lite", "passos": [{"dados": null, "ordem": 1, "filtros": "vendas de 01/12/2025 a 14/12/2025; marcas 10, 20, 30, 40, 50, 60", "situacao": "SUCESSO", "tempo_ms": 102, "descricao": "Bases de dez/2025: 467 pessoas no RH, 4967 vendas de 01/12 a 14/12, 24 linhas de % por marca e cargo", "ferramenta": "carregar_bases", "competencias": ["2025-12"], "mensagem_erro": null, "sql_executado": "SELECT f.matricula, to_char(fl.date_ref, 'YYYY-MM') AS competencia,\n       l.cod_loja, m.cod_marca, c.cod_cargo,\n       f.data_admissao, f.data_demissao\nFROM funcionario f\nJOIN funcionario_loja fl ON fl.funcionario_id = f.id\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = f.id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(fl.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT f.matricula, to_char(v.date_ref, 'YYYY-MM') AS competencia,\n       v.date_ref AS data_venda, v.vlr_venda::float8 AS vlr_venda,\n       l.cod_loja, m.cod_marca, c.cod_cargo\nFROM venda v\nJOIN funcionario f ON f.id = v.funcionario_id\nJOIN funcionario_loja fl ON fl.funcionario_id = v.funcionario_id\n     AND fl.date_ref = date_trunc('month', v.date_ref)::date\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = v.funcionario_id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(v.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT m.cod_marca, c.cod_cargo, mc.pct_comiss::float8 AS pct_comiss\nFROM marca_cargo mc\nJOIN marca m ON m.id = mc.marca_id\nJOIN cargo c ON c.id = mc.cargo_id\nWHERE mc.date_ref = (SELECT max(date_ref) FROM marca_cargo);", "tabelas_acessadas": ["cargo", "funcionario", "funcionario_cargo", "funcionario_loja", "loja", "marca", "marca_cargo", "venda"], "registros_retornados": 5458}, {"dados": null, "ordem": 2, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1050, "descricao": "Comissão atual (regras 5a a 5g): R$ 456.827,22", "ferramenta": "comissao_atual", "competencias": ["2025-12"], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 467}, {"dados": null, "ordem": 3, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 8115, "descricao": "Código gerado por gemini-3.5-flash-lite em 2 tentativas, conferido com o cálculo de referência", "ferramenta": "gerar_codigo", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 4, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1602, "descricao": "Código executado no sandbox", "ferramenta": "executar_sandbox", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 467}, {"dados": null, "ordem": 5, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 817, "descricao": "6 conferências passaram: colunas obrigatórias, mesmas pessoas e meses da comissão atual, sem comissão negativa, contribuições somam a diferença, escopo da regra, cálculo de referência", "ferramenta": "conferir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 6, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 2305, "descricao": "Custo adicional de R$ 64.649,63", "ferramenta": "resumir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}], "campanhas": [{"nome": "Especificação dez/25, item 6f", "tipo": "ACRESCIMO", "autor": null, "versao": null, "data_fim": "2025-12-31", "pct_novo": null, "aprovador": null, "aprovada_em": null, "campanha_id": null, "data_inicio": "2025-12-01", "justificativa": "Marcas 40, 50 e 60: +1% em todas as vendas de dez/25, exceto gerentes", "pct_acrescimo": 1.0}, {"nome": "Especificação dez/25, item 6g", "tipo": "ACRESCIMO", "autor": null, "versao": null, "data_fim": "2025-12-31", "pct_novo": null, "aprovador": null, "aprovada_em": null, "campanha_id": null, "data_inicio": "2025-12-01", "justificativa": "Marca 30: +0,5% em todas as vendas de dez/25, exceto gerentes", "pct_acrescimo": 0.5}], "premissas": ["Gerentes (150) excluídos", "Cargos elegíveis: 100, 200, 300", "Marcas incluídas: 10, 20, 30, 40, 50, 60", "Período: de 01/12/2025 a 14/12/2025", "Acréscimo de comissão: +0.5%", "Simulação sobre vendas que já aconteceram: supõe que as pessoas venderiam o mesmo com a regra nova.", "A comparação com a comissão atual é o número mais confiável; o total absoluto é apurado por nós, não é a folha oficial.", "A comissão atual ainda não aplica proporcional de admissão/demissão nem férias e afastamentos."], "tentativas": 2}, "impacto": {"pessoas_total": 467, "maior_acrescimo": 325.35, "media_por_pessoa": 164.09, "pessoas_impactadas": 394}, "retorno": {"provisorio": true, "custo_pct_venda": 0.49, "custo_por_real_acima_meta": 0.01}, "rule_id": "rule-sergio", "cenarios": [{"tipo": "sem_marca", "titulo": "Sem a marca Preto", "economia": 51288.28, "marcas_alvo": ["20", "30", "40", "50", "60"], "pct_acrescimo": 0.5, "cabe_no_orcamento": null, "custo_incremental": 13361.35}], "conflitos": [{"nome": "Especificação dez/25, item 6f", "tipo": "ACRESCIMO", "autor": null, "cargos": ["100", "200", "300"], "marcas": ["40", "50", "60"], "status": "APROVADA", "versao": null, "data_fim": "2025-12-31", "campanha_id": null, "data_inicio": "2025-12-01", "sobreposicao": {"data_fim": "2025-12-14", "data_inicio": "2025-12-01"}}, {"nome": "Especificação dez/25, item 6g", "tipo": "ACRESCIMO", "autor": null, "cargos": ["100", "200", "300"], "marcas": ["30"], "status": "APROVADA", "versao": null, "data_fim": "2025-12-31", "campanha_id": null, "data_inicio": "2025-12-01", "sobreposicao": {"data_fim": "2025-12-14", "data_inicio": "2025-12-01"}}], "orcamento": null, "por_cargo": [{"codigo": "100", "baseline": 259641.03, "simulado": 311386.37, "diferenca": 51745.34}, {"codigo": "150", "baseline": 127378.54, "simulado": 127378.54, "diferenca": 0.0}, {"codigo": "200", "baseline": 59046.07, "simulado": 68363.16, "diferenca": 9317.09}, {"codigo": "300", "baseline": 10761.58, "simulado": 14348.78, "diferenca": 3587.2}], "por_marca": [{"codigo": "10", "baseline": 351651.78, "simulado": 402940.06, "diferenca": 51288.28}, {"codigo": "20", "baseline": 40833.15, "simulado": 45912.59, "diferenca": 5079.44}, {"codigo": "30", "baseline": 15393.77, "simulado": 18980.97, "diferenca": 3587.2}, {"codigo": "40", "baseline": 43225.68, "simulado": 47210.98, "diferenca": 3985.3}, {"codigo": "50", "baseline": 3199.34, "simulado": 3656.4, "diferenca": 457.06}, {"codigo": "60", "baseline": 2523.5, "simulado": 2775.85, "diferenca": 252.35}], "ressalvas": ["Simulação sobre vendas que já aconteceram: supõe que as pessoas venderiam o mesmo com a regra nova.", "A comparação com a comissão atual é o número mais confiável; o total absoluto é apurado por nós, não é a folha oficial.", "A comissão atual ainda não aplica proporcional de admissão/demissão nem férias e afastamentos."], "explicacao": "No histórico, as vendas desse período somaram R$ 13.187.602,83, 440% da meta de R$ 3.000.000,00 (340% acima da meta), totalizando R$ 10.187.602,83 acima da meta. O custo extra da campanha é de R$ 64.649,63, representando 14% sobre a comissão atual de R$ 456.827,22, com 394 de 467 pessoas recebendo o acréscimo, em média R$ 164,09 cada e maior de R$ 325,35, sendo a loja 13 a com maior custo extra, com R$ 1.691,52, o que equivale a 2,6% do total. A maior parte do custo extra vem da marca Preto, concentrando 79% do total, e o cargo que mais recebe o acréscimo é o vendedor loja, com 80% do total. Para mitigar esse risco de concentração, o cenário calculado sem a marca Preto apresenta um acréscimo de 0,50% e um custo extra de R$ 13.361,35.", "observacao": "Resultado da IA conferido com o cálculo determinístico.", "tentativas": 2, "competencias": ["2025-12"], "maiores_lojas": 