  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-passada-julho', v_gabriela_id, 'usuario', NULL, NULL, $txt$Lana, qual foi o total de vendas e faturamento consolidado no mês de julho de 2025?$txt$, NULL, NULL, '2026-07-20 09:05:00+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-passada-julho', v_gabriela_id, 'lana', NULL, NULL, $txt$Consultei o histórico de vendas de julho de 2025. A rede registrou 5.018 vendas, totalizando R$ 18.683.547,69 no fechamento do mês.$txt$, NULL, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "consultar_banco", "descricao": "Vendas totais de jul/2025", "tabelas_acessadas": ["venda"], "competencias": ["2025-07"], "filtros": "vendas de 01/07/2025 em todas as lojas", "sql_executado": "SELECT COUNT(*) AS total_vendas, ROUND(SUM(vlr_venda)::numeric, 2) AS total_valor FROM venda WHERE date_ref = '2025-07-01' LIMIT 50", "registros_retornados": 1, "dados": [{"total_vendas": 5018, "total_valor": 18683547.69}], "tempo_ms": 300, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-07-20 09:05:05+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-passada-julho', v_gabriela_id, 'usuario', NULL, NULL, $txt$Quero cadastrar a Campanha de Inverno para o mês de julho inteiro (01 a 31/07/2025), todas as marcas, para os cargos 100 e 200, com 1,5% de comissão e meta de R$ 5.000.000,00.$txt$, NULL, NULL, '2026-07-20 09:10:00+00');
