  INSERT INTO campanha_versao (campanha_id, numero, simulacao_id, regra, resultado, data_inicio, data_fim, ultima_mensagem_id, submetida_em)
  VALUES (v_camp_id, 1, v_sim_id, $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-passada", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-07-31", "data_inicio": "2025-07-01"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 1.0, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["ALL"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 5000000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Campanha de Inverno Julho 1% de 01 a 31/07/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $json${"meta": {"atingida": true, "diferenca": 13683547.69, "meta_vendas": 5000000.0, "vendas_periodo": 18683547.69, "pct_atingimento": 373.67}, "codigo": "import pandas as pd\nimport numpy as np\nfrom datetime import datetime\n\nDATA_INICIO = \"2025-07-01\"\nDATA_FIM = \"2025-07-31\"\nPCT_ACRESCIMO = 1.0\nMARCAS_ALVO = [\"10\", \"20\", \"30\", \"40\", \"50\", \"60\"]\nCARGOS_ALVO = [\"100\", \"200\"]\n\ndef aplicar_regra(bases, apuracao_base, competencias):\n    vendas = bases[\"vendas\"].copy()\n    \n    # Garantir formato datetime na data_venda\n    vendas[\"data_venda\"] = pd.to_datetime(vendas[\"data_venda\"])\n    \n    dt_inicio = pd.to_datetime(DATA_INICIO)\n    dt_fim = pd.to_datetime(DATA_FIM)\n    \n    # Filtrar vendas na janela de datas da regra\n    vendas_periodo = vendas[(vendas[\"data_venda\"] >= dt_inicio) & (vendas[\"data_venda\"] <= dt_fim)]\n    \n    # Base de cálculo na janela para o acréscimo (+1 p.p.):\n    # - Cargo 150 (Gerente): soma TODAS as vendas da loja no período (sem filtrar por cargo)\n    # - Outros cargos (ex: 100, 200): soma apenas as vendas da própria matrícula na janela\n    \n    # 1. Base para cargo 150 (total da loja)\n    vendas_loja = vendas_periodo.groupby([\"cod_loja\", \"competencia\"], as_index=False)[\"vlr_venda\"].sum()\n    vendas_loja = vendas_loja.rename(columns={\"vlr_venda\": \"base_acrescimo_loja\"})\n    \n    # 2. Base para os demais cargos (proprias vendas)\n    vendas_matricula = vendas_periodo.groupby([\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"], as_index=False)[\"vlr_venda\"].sum()\n    vendas_matricula = vendas_matricula.rename(columns={\"vlr_venda\": \"base_acrescimo_mat\"})\n    \n    # Copiar apuracao_base para apuracao_simulada\n    apuracao_simulada = apuracao_base.copy()\n    \n    # Juntar as bases de acréscimo na apuração\n    apuracao_simulada[\"matricula\"] = apuracao_simulada[\"matricula\"].astype(str)\n    apuracao_simulada[\"competencia\"] = apuracao_simulada[\"competencia\"].astype(str)\n    apuracao_simulada[\"cod_loja\"] = apuracao_simulada[\"cod_loja\"].astype(str)\n    apuracao_simulada[\"cod_marca\"] = apuracao_simulada[\"cod_marca\"].astype(str)\n    apuracao_simulada[\"cod_cargo\"] = apuracao_simulada[\"cod_cargo\"].astype(str)\n    \n    apuracao_simulada = apuracao_simulada.merge(\n        vendas_matricula, \n        on=[\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"], \n        how=\"left\"\n    )\n    apuracao_simulada[\"base_acrescimo_mat\"] = apuracao_simulada[\"base_acrescimo_mat\"].fillna(0.0)\n    \n    apuracao_simulada = apuracao_simulada.merge(\n        vendas_loja, \n        on=[\"cod_loja\", \"competencia\"], \n        how=\"left\"\n    )\n    apuracao_simulada[\"base_acrescimo_loja\"] = apuracao_simulada[\"base_acrescimo_loja\"].fillna(0.0)\n    \n    # Identificar quem é alvo\n    is_alvo = apuracao_simulada[\"cod_marca\"].isin(MARCAS_ALVO) & apuracao_simulada[\"cod_cargo\"].isin(CARGOS_ALVO)\n    \n    # Calcular o delta para quem é alvo\n    # Se cod_cargo == \"150\", a base é a da loja. Caso contrário, é a da matrícula.\n    base_efetiva = np.where(\n        apuracao_simulada[\"cod_cargo\"] == \"150\",\n        apuracao_simulada[\"base_acrescimo_loja\"],\n        apuracao_simulada[\"base_acrescimo_mat\"]\n    )\n    \n    delta_calculado = np.where(\n        is_alvo,\n        base_efetiva * (PCT_ACRESCIMO / 100.0),\n        0.0\n    )\n    \n    apuracao_simulada[\"delta\"] = [round(d, 2) for d in delta_calculado]\n    \n    # Garantir que comissao nova não fique negativa\n    nova_comissao = apuracao_simulada[\"comissao\"] + apuracao_simulada[\"delta\"]\n    apuracao_simulada[\"comissao\"] = np.maximum(0.0, nova_comissao).round(2)\n    \n    # Recalcular delta exato após arredondamentos e limite inferior\n    apuracao_simulada[\"delta\"] = (apuracao_simulada[\"comissao\"] - apuracao_base[\"comissao\"]).round(2)\n    \n    # Remover colunas auxiliares da apuracao_simulada\n    apuracao_simulada = apuracao_simulada.drop(columns=[\"base_acrescimo_mat\", \"base_acrescimo_loja\"])\n    \n    # Montar o dataframe de contribuicoes (apenas linhas com delta != 0)\n    df_contrib = apuracao_simulada[apuracao_simulada[\"delta\"] != 0.0].copy()\n    df_contrib[\"elemento_ref\"] = \"pct_acrescimo\"\n    \n    contribuicoes = df_contrib[[\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\", \"elemento_ref\", \"delta\"]].copy()\n    \n    return {\n        \"apuracao_simulada\": apuracao_simulada.drop(columns=[\"delta\"]),\n        \"contribuicoes\": contribuicoes\n    }\n", "totais": {"baseline": 657997.76, "simulado": 837631.15, "diferenca": 179633.39, "diferenca_pct": 27.3}, "trilha": {"modelo": "gemini-3.5-flash-lite", "passos": [{"dados": null, "ordem": 1, "filtros": "vendas de 01/07/2025 a 31/07/2025; marcas 10, 20, 30, 40, 50, 60", "situacao": "SUCESSO", "tempo_ms": 130, "descricao": "Bases de jul/2025: 322 pessoas no RH, 5018 vendas de 01/07 a 31/07, 24 linhas de % por marca e cargo", "ferramenta": "carregar_bases", "competencias": ["2025-07"], "mensagem_erro": null, "sql_executado": "SELECT f.matricula, to_char(fl.date_ref, 'YYYY-MM') AS competencia,\n       l.cod_loja, m.cod_marca, c.cod_cargo,\n       f.data_admissao, f.data_demissao\nFROM funcionario f\nJOIN funcionario_loja fl ON fl.funcionario_id = f.id\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = f.id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(fl.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT f.matricula, to_char(v.date_ref, 'YYYY-MM') AS competencia,\n       v.date_ref AS data_venda, v.vlr_venda::float8 AS vlr_venda,\n       l.cod_loja, m.cod_marca, c.cod_cargo\nFROM venda v\nJOIN funcionario f ON f.id = v.funcionario_id\nJOIN funcionario_loja fl ON fl.funcionario_id = v.funcionario_id\n     AND fl.date_ref = date_trunc('month', v.date_ref)::date\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = v.funcionario_id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(v.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT m.cod_marca, c.cod_cargo, mc.pct_comiss::float8 AS pct_comiss\nFROM marca_cargo mc\nJOIN marca m ON m.id = mc.marca_id\nJOIN cargo c ON c.id = mc.cargo_id\nWHERE mc.date_ref = (SELECT max(date_ref) FROM marca_cargo);", "tabelas_acessadas": ["cargo", "funcionario", "funcionario_cargo", "funcionario_loja", "loja", "marca", "marca_cargo", "venda"], "registros_retornados": 5364}, {"dados": null, "ordem": 2, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 802, "descricao": "Comissão atual (regras 5a a 5g): R$ 657.997,76", "ferramenta": "comissao_atual", "competencias": ["2025-07"], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 322}, {"dados": null, "ordem": 3, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 3728, "descricao": "Código gerado por gemini-3.5-flash-lite em 1 tentativa, conferido com o cálculo de referência", "ferramenta": "gerar_codigo", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 4, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 815, "descricao": "Código executado no sandbox", "ferramenta": "executar_sandbox", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 322}, {"dados": null, "ordem": 5, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 799, "descricao": "6 conferências passaram: colunas obrigatórias, mesmas pessoas e meses da comissão atual, sem comissão negativa, contribuições somam a diferença, escopo da regra, cálculo de referência", "ferramenta": "conferir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 6, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 2580, "descricao": "Custo adicional de R$ 179.633,39", "ferramenta": "resumir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}], "campanhas": [], "premissas": ["Gerentes (150) excluídos", "Cargos elegíveis: 100, 200", "Marcas incluídas: 10, 20, 30, 40, 50, 60", "Período: de 01/07/2025 a 31/07/2025", "Acréscimo de comissão: +1.0%", "Simulação sobre vendas que já aconteceram: supõe que as pessoas venderiam o mesmo com a regra nova.", "A comparação com a comissão atual é o número mais confiável; o total absoluto é apurado por nós, não é a folha oficial.", "A comissão atual ainda não aplica proporcional de admissão/demissão nem férias e afastamentos."], "tentativas": 1}, "impacto": {"pessoas_total": 322, "maior_acrescimo": 2083.1, "media_por_pessoa": 748.47, "pessoas_impactadas": 240}, "retorno": {"provisorio": true, "custo_pct_venda": 0.96, "custo_por_real_acima_meta": 0.01}, "rule_id": "rule-passada", "cenarios": [{"tipo": "sem_marca", "titulo": "Sem a marca Preto", "economia": 152572.76, "marcas_alvo": ["20", "30", "40", "50", "60"], "pct_acrescimo": 1.0, "cabe_no_orcamento": null, "custo_incremental": 27060.63}], "conflitos": [], "orcamento": null, "por_cargo": [{"codigo": "100", "baseline": 403070.33, "simulado": 564045.54, "diferenca": 160975.21}, {"codigo": "150", "baseline": 200448.02, "simulado": 200448.02, "diferenca": 0.0}, {"codigo": "200", "baseline": 51195.45, "simulado": 69853.63, "diferenca": 18658.18}, {"codigo": "300", "baseline": 3283.96, "simulado": 3283.96, "diferenca": 0.0}], "por_marca": [{"codigo": "10", "baseline": 543067.72, "simulado": 695640.48, "diferenca": 152572.76}, {"codigo": "20", "baseline": 32115.07, "simulado": 40743.77, "diferenca": 8628.7}, {"codigo": "30", "baseline": 6568.8, "simulado": 6568.8, "diferenca": 0.0}, {"codigo": "40", "baseline": 47408.97, "simulado": 57605.89, "diferenca": 10196.92}, {"codigo": "50", "baseline": 28837.2, "simulado": 37072.21, "diferenca": 8235.01}, {"codigo": "60", "baseline": 0.0, "simulado": 0.0, "diferenca": 0.0}], "ressalvas": ["Simulação sobre vendas que já aconteceram: supõe que as pessoas venderiam o mesmo com a regra nova.", "A comparação com a comissão atual é o número mais confiável; o total absoluto é apurado por nós, não é a folha oficial.", "A comissão atual ainda não aplica proporcional de admissão/demissão nem férias e afastamentos."], "explicacao": "No histórico, as vendas desse período somaram R$ 18.683.547,69, 374% da meta de R$ 5.000.000,00, que são 274% acima da meta e R$ 13.683.547,69 acima da meta. O custo extra da campanha foi de R$ 179.633,39, representando 27% sobre a comissão atual de R$ 657.997,76. Desse total, 240 de 322 pessoas recebem o acréscimo, com média de R$ 748,47 cada e maior valor de R$ 2.083,10, sendo a loja 16 a com maior custo extra de R$ 10.780,52, o que equivale a 6,0% do total. A maior parte do custo extra está na marca Preto, com 85% do total, e o cargo que mais recebe o acréscimo é o de vendedor loja, com 90% do total. O que mais pesa no custo é a marca Preto puxada pelos vendedores de loja, e o cenário calculado sem a marca Preto apresenta acréscimo de 1,00% com custo extra de R$ 27.060,63.", "observacao": "Resultado da IA conferido com o cálculo determinístico.", "tentativas": 1, "competencias": ["2025-07"], "maiores_lojas": [{"codigo": "16", "baseline": 37930.89, "simulado": 48711.41, "diferenca": 10780.52}, {"codigo": "9", "baseline": 29332.57, "simulado": 37674.75, "diferenca": 8342.18}, {"codigo": "59", "baseline": 28837.2, "simulado": 37072.21, "diferenca": 8235.01}, {"codigo": "13", "baseline": 27719.12, "simulado": 35636.15, "diferenca": 7917.03}, {"codigo": "24", "baseline": 24637.78, "simulado": 31676.77, "diferenca": 7038.99}], "origem_codigo": "llm", "comissao_periodo": [{"cargo": "100", "marca": "10", "data_fim": "2025-07-31", "pct_base": 2.5, "historico": [], "data_inicio": "2025-07-01", "pct_vigente": 2.5, "pct_com_campanha": 3.5}, {"cargo": "200", "marca": "10", "data_fim": "2025-07-31", "pct_base": 2.0, "historico": [], "data_inicio": "2025-07-01", "pct_vigente": 2.0, "pct_com_campanha": 3.0}, {"cargo": "100", "marca": "20", "data_fim": "2025-07-31", "pct_base": 3.0, "historico": [], "data_inicio": "2025-07-01", "pct_vigente": 3.0, "pct_com_campanha": 4.0}, {"cargo": "200", "marca": "20", "data_fim": "2025-07-31", "pct_base": 2.5, "historico": [], "data_inicio": "2025-07-01", "pct_vigente": 2.5, "pct_com_campanha": 3.5}, {"cargo": "100", "marca": "30", "data_fim": "2025-07-31", "pct_base": 2.0, "historico": [], "data_inicio": "2025-07-01", "pct_vigente": 2.0, "pct_com_campanha": 3.0}, {"cargo": "200", "marca": "30", "data_fim": "2025-07-31", "pct_base": 1.5, "historico": [], "data_inicio": "2025-07-01", "pct_vigente": 1.5, "pct_com_campanha": 2.5}, {"cargo": "100", "marca": "40", "data_fim": "2025-07-31", "pct_base": 3.5, "historico": [], "data_inicio": "2025-07-01", "pct_vigente": 3.5, "pct_com_campanha": 4.5}, {"cargo": "200", "marca": "40", "data_fim": "2025-07-31", "pct_base": 3.0, "historico": [], "data_inicio": "2025-07-01", "pct_vigente": 3.0, "pct_com_campanha": 4.0}, {"cargo": "100", "marca": "50", "data_fim": "2025-07-31", "pct_base": 2.5, "historico": [], "data_inicio": "2025-07-01", "pct_vigente": 2.5, "pct_com_campanha": 3.5}, {"cargo": "200", "marca": "50", "data_fim": "2025-07-31", "pct_base": 2.0, "historico": [], "data_inicio": "2025-07-01", "pct_vigente": 2.0, "pct_com_campanha": 3.0}, {"cargo": "100", "marca": "60", "data_fim": "2025-07-31", "pct_base": 3.0, "historico": [], "data_inicio": "2025-07-01", "pct_vigente": 3.0, "pct_com_campanha": 4.0}, {"cargo": "200", "marca": "60", "data_fim": "2025-07-31", "pct_base": 2.5, "historico": [], "data_inicio": "2025-07-01", "pct_vigente": 2.5, "pct_com_campanha": 3.5}]}$json$::jsonb, '2025-07-01', '2025-07-31', v_msg_id, '2026-07-20 10:00:00+00')
