  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-rascunho-silvia', v_silvia_id, 'lana', NULL, NULL, $txt$Consultei o banco para 01/11/2025. As marcas Preto (10) e Branco (20) somaram R$ 10.085.948,83 em 3.727 vendas: a PRETO com R$ 9.042.539,98 (3.285 vendas) e a BRANCO com R$ 1.043.408,85 (442 vendas).$txt$, NULL, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "consultar_banco", "descricao": "Vendas marcas 10 e 20 em 01/11/2025", "tabelas_acessadas": ["funcionario_loja", "loja", "marca", "venda"], "competencias": ["2025-11"], "filtros": "vendas de 01/11/2025 para marcas 10 e 20", "sql_executado": "SELECT m.cod_marca, m.descr_marca, COUNT(*) AS qtd_vendas, ROUND(SUM(v.vlr_venda)::numeric, 2) AS total_valor FROM venda v JOIN funcionario_loja fl ON fl.funcionario_id = v.funcionario_id AND fl.date_ref = '2025-11-01' JOIN loja l ON l.id = fl.loja_id JOIN marca m ON m.id = l.marca_id WHERE v.date_ref = '2025-11-01' AND m.cod_marca IN ('10', '20') GROUP BY m.cod_marca, m.descr_marca ORDER BY m.cod_marca LIMIT 50", "registros_retornados": 2, "dados": [{"cod_marca": "10", "descr_marca": "PRETO", "qtd_vendas": 3285, "total_valor": 9042539.98}, {"cod_marca": "20", "descr_marca": "BRANCO", "qtd_vendas": 442, "total_valor": 1043408.85}], "tempo_ms": 310, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-25 15:02:05+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-rascunho-silvia', v_silvia_id, 'usuario', NULL, NULL, $txt$Estou rascunhando um incentivo de abertura de verão: de 01 a 15/11/2025, para as marcas Preto e Branco, cobrindo cargos 100, 200 e 300, com +1,0%.$txt$, NULL, NULL, '2026-10-25 15:05:00+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-rascunho-silvia', v_silvia_id, 'lana', NULL, NULL, $txt$Registrei os parâmetros para as marcas 10 e 20 no período de 01 a 15/11/2025 com acréscimo de 1,0% para cargos 100, 200 e 300. Falta definir a Meta Financeira da Campanha. Qual o valor?$txt$, $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-silvia", "faltantes": ["meta_vendas"], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-11-15", "data_inicio": "2025-11-01"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 1.0, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["10", "20"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": null, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Incentivo Verão 1,0% marcas 10 e 20 de 01 a 15/11/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "registrar_parametros_regra", "descricao": "Ficha da campanha registrada; falta informar: Meta Financeira da Campanha (R$)", "tabelas_acessadas": [], "competencias": ["2025-11"], "filtros": "marcas: 10, 20; cargos: 100, 200, 300; periodo: data_inicio: 2025-11-01; data_fim: 2025-11-15", "sql_executado": null, "registros_retornados": 0, "dados": null, "tempo_ms": 0, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-25 15:05:04+00');
