s_regra", "descricao": "Ficha da campanha registrada", "tabelas_acessadas": [], "competencias": ["2025-11"], "filtros": "marcas: 10, 20; cargos: 100, 200, 300; meta: 2000000.00; periodo: 2025-11-01 a 2025-11-15", "sql_executado": null, "registros_retornados": 0, "dados": null, "tempo_ms": 0, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-25 15:07:34+00');
  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
