  INSERT INTO mensagem_chat (chat_id, usuario_id, papel, tipo, simulacao_id, texto, ficha, trilha, criada_em)
  VALUES ('demo-chat-rascunho-silvia', v_silvia_id, 'lana', NULL, NULL, $txt$Acréscimo alterado para 1,2%! Ficha confirmada com marcas 10 e 20, cargos 100, 200 e 300, de 01 a 15/11/2025 e meta de R$ 2.000.000,00.$txt$, $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-silvia", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-11-15", "data_inicio": "2025-11-01"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 1.2, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["10", "20"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 2000000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Campanha Especial de Marcas 1,2% de 01 a 15/11/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $trilha${"modelo": "gemini-3.5-flash-lite", "tentativas": null, "premissas": [], "passos": [{"ordem": 1, "ferramenta": "registrar_parametros_regra", "descricao": "Ficha da campanha registrada", "tabelas_acessadas": [], "competencias": ["2025-11"], "filtros": "marcas: 10, 20; cargos: 100, 200, 300; pct: 1.2; meta: 2000000.00; periodo: 2025-11-01 a 2025-11-15", "sql_executado": null, "registros_retornados": 0, "dados": null, "tempo_ms": 0, "situacao": "SUCESSO", "mensagem_erro": null}]}$trilha$::jsonb, '2026-10-25 15:10:04+00');
  INSERT INTO simulacao (usuario_id, chat_id, campanha_id, status, etapa, ficha, resultado, modelo, tentativas, criada_em, concluida_em)
  VALUES (v_silvia_id, 'demo-chat-rascunho-silvia', v_camp_id, 'CONCLUIDA', 'Concluída', $json${"status": "DRAFT_PENDING_REVIEW", "rule_id": "rule-silvia", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_fim": "2025-11-15", "data_inicio": "2025-11-01"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acréscimo de Comissão (%)", "value": 1.2, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["10", "20"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Elegíveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 2000000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Orçamento Máximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Campanha Especial de Marcas 1,2% de 01 a 15/11/2025", "tipo_regra": "BONUS_TEMPORARIO"}$json$::jsonb, $json${"meta": {"atingida": true, "diferenca": 8085948.83, "meta_vendas": 2000000.0, "vendas_periodo": 10085948.83, "pct_atingimento": 504.3}, "codigo": "import pandas as pd\nimport numpy as np\nimport math\nfrom datetime import datetime\n\nDATA_INICIO = \"2025-11-01\"\nDATA_FIM = \"2025-11-15\"\nPCT_ACRESCIMO = 1.2\nMARCAS_ALVO = [\"10\", \"20\"]\nCARGOS_ALVO = [\"100\", \"200\", \"300\"]\n\ndef aplicar_regra(bases, apuracao_base, competencias):\n    \"\"\"\n    Aplica a regra de comissionamento para o período especificado.\n    Regra:\n      - Período da regra: 2025-11-01 a 2025-11-15 (inclusive).\n      - Marcas alvo: '10', '20'.\n      - Cargos alvo: '100', '200', '300'.\n      - Acréscimo de +1.2 pontos percentuais na comissão sobre as vendas ocorridas\n        exclusivamente dentro do período da regra.\n      - Para cargos normais ('100', '200', '300'), a base é a soma das vendas próprias\n        na janela da regra.\n      - Para o GERENTE ('150'), caso ele estivesse elegível (mas ele não está nos cargos alvo,\n        embora a regra cite o comportamento do gerente nas instruções, aqui os cargos alvo são 100, 200, 300).\n        Como '150' não está nos cargos alvo, gerentes não recebem o acréscimo.\n    \"\"\"\n    vendas = bases[\"vendas\"]\n    \n    # Converter data_venda para datetime se já não for\n    vendas_dt = pd.to_datetime(vendas[\"data_venda\"])\n    dt_inicio = pd.to_datetime(DATA_INICIO)\n    dt_fim = pd.to_datetime(DATA_FIM)\n    \n    # Filtrar vendas na janela da regra\n    mask_janela = (vendas_dt >= dt_inicio) & (vendas_dt <= dt_fim)\n    vendas_janela = vendas[mask_janela].copy()\n    \n    # Garantir tipos texto\n    for df_name in [\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"]:\n        if df_name in vendas_janela.columns:\n            vendas_janela[df_name] = vendas_janela[df_name].astype(str)\n            \n    # Filtrar marcas e cargos alvo\n    mask_alvo = (\n        vendas_janela[\"cod_marca\"].isin(MARCAS_ALVO) &\n        vendas_janela[\"cod_cargo\"].isin(CARGOS_ALVO)\n    )\n    vendas_alvo = vendas_janela[mask_alvo]\n    \n    # Calcular base de cálculo na janela para cada matrícula e competência\n    # (Para os cargos alvo, é a soma das próprias vendas na janela)\n    base_janela = (\n        vendas_alvo.groupby([\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\"], as_index=False)\n        [\"vlr_venda\"]\n        .sum()\n        .rename(columns={\"vlr_venda\": \"vlr_janela\"})\n    )\n    \n    # Delta da comissão = vlr_janela * (PCT_ACRESCIMO / 100)\n    base_janela[\"delta_calc\"] = base_janela[\"vlr_janela\"] * (PCT_ACRESCIMO / 100.0)\n    \n    # Agrupar caso haja multiplas linhas (embora venha agrupado)\n    delta_agrupado = (\n        base_janela.groupby([\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\"], as_index=False)\n        [\"delta_calc\"]\n        .sum()\n    )\n    \n    # Preparar apuracao_simulada baseada em apuracao_base\n    apuracao_simulada = apuracao_base.copy()\n    \n    # Garantir tipos texto em apuracao_simulada\n    for col in [\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"]:\n        if col in apuracao_simulada.columns:\n            apuracao_simulada[col] = apuracao_simulada[col].astype(str)\n            \n    # Mesclar com os deltas calculados\n    apuracao_simulada = pd.merge(\n        apuracao_simulada,\n        delta_agrupado[[\"matricula\", \"competencia\", \"delta_calc\"]],\n        on=[\"matricula\", \"competencia\"],\n        how=\"left\"\n    )\n    \n    apuracao_simulada[\"delta_calc\"] = apuracao_simulada[\"delta_calc\"].fillna(0.0)\n    \n    # Atualizar comissao\n    nova_comissao = apuracao_simulada[\"comissao\"] + apuracao_simulada[\"delta_calc\"]\n    # Comissão nunca pode ficar negativa\n    nova_comissao = nova_comissao.apply(lambda x: max(0.0, x))\n    \n    # Recalcular delta real aplicado (considerando arredondamentos)\n    delta_real = nova_comissao - apuracao_simulada[\"comissao\"]\n    apuracao_simulada[\"comissao\"] = nova_comissao.round(2)\n    \n    # Remover colunas temporárias se houver\n    if \"delta_calc\" in apuracao_simulada.columns:\n        apuracao_simulada = apuracao_simulada.drop(columns=[\"delta_calc\"])\n        \n    # Construir dataframe de contribuicoes\n    # Filtrar apenas quem teve delta != 0 (ou delta arredondado != 0)\n    contribuicoes_df = apuracao_base[[\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\"]].copy()\n    for col in contribuicoes_df.columns:\n        contribuicoes_df[col] = contribuicoes_df[col].astype(str)\n        \n    contribuicoes_df[\"delta\"] = (apuracao_simulada[\"comissao\"] - apuracao_base[\"comissao\"]).round(2)\n    contribuicoes_df[\"elemento_ref\"] = \"pct_acrescimo\"\n    \n    # Filtrar apenas linhas onde delta != 0\n    contribuicoes_df = contribuicoes_df[contribuicoes_df[\"delta\"] != 0.0].copy()\n    \n    # Reordenar colunas de contribuicoes\n    contribuicoes_df = contribuicoes_df[\n        [\"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\", \"elemento_ref\", \"delta\"]\n    ]\n    \n    return {\n        \"apuracao_simulada\": apuracao_simulada,\n        \"contribuicoes\": contribuicoes_df\n    }\n", "totais": {"baseline": 515738.39, "simulado": 634403.8, "diferenca": 118665.41, "diferenca_pct": 23.01}, "trilha": {"modelo": "gemini-3.5-flash-lite", "passos": [{"dados": null, "ordem": 1, "filtros": "vendas de 01/11/2025 a 15/11/2025; marcas 10, 20", "situacao": "SUCESSO", "tempo_ms": 131, "descricao": "Bases de nov/2025: 469 pessoas no RH, 3727 vendas de 01/11 a 15/11, 24 linhas de % por marca e cargo", "ferramenta": "carregar_bases", "competencias": ["2025-11"], "mensagem_erro": null, "sql_executado": "SELECT f.matricula, to_char(fl.date_ref, 'YYYY-MM') AS competencia,\n       l.cod_loja, m.cod_marca, c.cod_cargo,\n       f.data_admissao, f.data_demissao\nFROM funcionario f\nJOIN funcionario_loja fl ON fl.funcionario_id = f.id\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = f.id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(fl.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT f.matricula, to_char(v.date_ref, 'YYYY-MM') AS competencia,\n       v.date_ref AS data_venda, v.vlr_venda::float8 AS vlr_venda,\n       l.cod_loja, m.cod_marca, c.cod_cargo\nFROM venda v\nJOIN funcionario f ON f.id = v.funcionario_id\nJOIN funcionario_loja fl ON fl.funcionario_id = v.funcionario_id\n     AND fl.date_ref = date_trunc('month', v.date_ref)::date\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = v.funcionario_id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(v.date_ref, 'YYYY-MM') = ANY(%(competencias)s);\nSELECT m.cod_marca, c.cod_cargo, mc.pct_comiss::float8 AS pct_comiss\nFROM marca_cargo mc\nJOIN marca m ON m.id = mc.marca_id\nJOIN cargo c ON c.id = mc.cargo_id\nWHERE mc.date_ref = (SELECT max(date_ref) FROM marca_cargo);", "tabelas_acessadas": ["cargo", "funcionario", "funcionario_cargo", "funcionario_loja", "loja", "marca", "marca_cargo", "venda"], "registros_retornados": 5491}, {"dados": null, "ordem": 2, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1116, "descricao": "Comissão atual (regras 5a a 5g): R$ 515.738,39", "ferramenta": "comissao_atual", "competencias": ["2025-11"], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 469}, {"dados": null, "ordem": 3, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 5357, "descricao": "Código gerado por gemini-3.5-flash-lite em 1 tentativa, conferido com o cálculo de referência", "ferramenta": "gerar_codigo", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 4, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 856, "descricao": "Código executado no sandbox", "ferramenta": "executar_sandbox", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 469}, {"dados": null, "ordem": 5, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 794, "descricao": "6 conferências passaram: colunas obrigatórias, mesmas pessoas e meses da comissão atual, sem comissão negativa, contribuições somam a diferença, escopo da regra, cálculo de referência", "ferramenta": "conferir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 6, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1380, "descricao": "Custo adicional de R$ 118.665,41", "ferramenta": "resumir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}], "campanhas": [], "premissas": ["Gerentes (150) excluídos", "Cargos elegíveis: 100, 200, 300", "Marcas incluídas: 10, 20", "Período: de 01/11/2025 a 15/11/2025", "Acréscimo de comissão: +1.2%", "Simulação sobre vendas que já aconteceram: supõe que as pessoas venderiam o mesmo com a regra nova.", "A comparação com a comissão atual é o número mais confiável; o total absoluto é apurado por nós, não é a folha oficial.", "A comissão atual ainda não aplica proporcional de admissão/demissão nem férias e afastamentos."], "tentativas": 1}, "impacto": {"pessoas_total": 469, "maior_acrescimo": 813.47, "media_por_pessoa": 345.96, "pessoas_impactadas": 343}, "retorno": {"provisorio": true, "custo_pct_venda": 1.18, "custo_por_real_acima_meta": 0.01}, "rule_id": "rule-silvia", "cenarios": [{"tipo": "sem_marca", "titulo": "Sem a marca Preto", "economia": 106237.97, "marcas_alvo": ["20"], "pct_acrescimo": 1.2, "cabe_no_orcamento": null, "custo_incremental": 12427.44}], "conflitos": [], "orcamento": null, "por_cargo": [{"codigo": "100", "baseline": 291061.06, "simulado": 397299.03, "diferenca": 106237.97}, {"codigo": "150", "baseline": 155412.93, "simulado": 155412.93, "diferenca": 0.0}, {"codigo": "200", "baseline": 63708.26, "simulado": 76135.7, "diferenca": 12427.44}, {"codigo": "300", "baseline": 5556.14, "simulado": 5